# ============================================================
# MONEY HELPERS
# ============================================================

def D(value) -> Decimal:
    if isinstance(value, Decimal):
        return value

    if value is None:
        return Decimal("0")

    try:
        return Decimal(str(value))
    except (InvalidOperation, ValueError, TypeError):
        return Decimal("0")


def money(value) -> str:
    amount = D(value).quantize(
        Decimal("0.01"),
        rounding=ROUND_DOWN,
    )
    return f"${amount:,.2f}"


GAME_COLOR = 0x0759D8
INFO_COLOR = 0xFEE75C

def points_from_usd(value) -> Decimal:
    # Compatibility wrapper: all balances and bets are USD.
    return D(value).quantize(Decimal("0.01"), rounding=ROUND_DOWN)

def points_text(value) -> str:
    # Compatibility wrapper for old call sites; always displays dollars.
    return money(value)

def usd_from_points_admin(raw) -> Optional[Decimal]:
    # Admin amounts are direct USD values.
    value = str(raw).strip().lower().replace(",", "").replace("$", "")
    for suffix in ("usd", "dollars", "dollar"):
        if value.endswith(suffix):
            value = value[:-len(suffix)].strip()
            break
    try:
        amount = Decimal(value)
    except (InvalidOperation, ValueError, TypeError):
        return None
    if amount <= 0:
        return None
    return amount.quantize(Decimal("0.01"), rounding=ROUND_DOWN)

def usd_from_points_input(raw, balance_usd) -> Optional[Decimal]:
    value = str(raw).strip().lower().replace(",", "").replace("$", "")
    if value in {"all", "max"}:
        return D(balance_usd)
    if value == "half":
        return (D(balance_usd) / Decimal("2")).quantize(Decimal("0.01"), rounding=ROUND_DOWN)
    try:
        amount = Decimal(value)
    except (InvalidOperation, ValueError, TypeError):
        return None
    if amount <= 0:
        return None
    return amount.quantize(Decimal("0.01"), rounding=ROUND_DOWN)

def bet_display(value) -> str:
    return f"**{points_text(value)}** · `{money(value)}`"


def plain_money(value) -> str:
    amount = D(value).quantize(
        Decimal("0.01"),
        rounding=ROUND_DOWN,
    )
    return f"{amount:,.2f}"


def parse_money(value: str | int | float | Decimal) -> Optional[Decimal]:
    if value is None:
        return None

    if isinstance(value, Decimal):
        amount = value
    else:
        raw = str(value).strip().replace(",", "").replace("$", "")

        if raw.lower() in {"all", "half"}:
            return None

        try:
            amount = Decimal(raw)
        except InvalidOperation:
            return None

    if amount <= 0:
        return None

    return amount.quantize(
        Decimal("0.01"),
        rounding=ROUND_DOWN,
    )


def normalize_amount(value: str) -> Optional[Decimal]:
    raw = str(value).strip().lower()

    if raw.endswith("$"):
        raw = raw[:-1]

    return parse_money(raw)


def amount_or_all(
    raw: str,
    balance: Decimal,
) -> Optional[Decimal]:

    value = str(raw).strip().lower()

    if value in {"all", "max"}:
        return balance

    if value == "half":
        return (
            balance / Decimal("2")
        ).quantize(
            Decimal("0.01"),
            rounding=ROUND_DOWN,
        )

    return normalize_amount(value)


def valid_bet(amount: Decimal) -> bool:
    return amount >= MIN_BET


