# ============================================================
# MINES GAME STATE
# ============================================================

class MinesGame:
    def __init__(
        self,
        bot: "CasinoBot",
        user_id: int,
        amount: Decimal,
        mines: int,
        game_id: int,
        server_hash: str,
        server_seed: str,
        client_seed: str,
        nonce: int,
    ):

        self.bot = bot
        self.user_id = user_id
        self.amount = amount
        self.mines = mines
        self.game_id = game_id

        self.server_hash = server_hash
        self.server_seed = server_seed
        self.client_seed = client_seed
        self.nonce = nonce

        # Mines are derived from the committed server seed, not Python's random module.
        positions = list(range(25))
        positions = bot.fair_shuffle(
            positions, server_seed, client_seed, nonce, "mines"
        )
        self.bombs = set(positions[:mines])

        self.opened: set[int] = set()
        self.finished = False

    @property
    def multiplier(self) -> Decimal:

        opened = len(self.opened)

        if opened <= 0:
            return Decimal("1.00")

        value = (
            Decimal("25")
            / Decimal(str(25 - self.mines))
        ) ** opened

        value *= Decimal("0.96")

        return value.quantize(
            Decimal("0.01"),
            rounding=ROUND_DOWN,
        )

    @property
    def payout(self) -> Decimal:
        return (
            self.amount * self.multiplier
        ).quantize(
            Decimal("0.01"),
            rounding=ROUND_DOWN,
        )


def create_mines_board_image(game: MinesGame) -> discord.File:
    """Render a fresh 5x5 Artic Mines board for each state change."""
    W, H = 1200, 720
    im=Image.new("RGB",(W,H),(255,255,255)); d=ImageDraw.Draw(im)
    def f(sz,bold=False):
        names = ([
            "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf",
            "/usr/share/fonts/truetype/liberation2/LiberationSans-Bold.ttf",
            "/usr/share/fonts/truetype/freefont/FreeSansBold.ttf",
            "/usr/local/share/fonts/DejaVuSans-Bold.ttf",
        ] if bold else [
            "/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf",
            "/usr/share/fonts/truetype/liberation2/LiberationSans-Regular.ttf",
            "/usr/share/fonts/truetype/freefont/FreeSans.ttf",
            "/usr/local/share/fonts/DejaVuSans.ttf",
        ])
        for path in names:
            try:
                if os.path.isfile(path): return ImageFont.truetype(path, sz)
            except Exception:
                pass
        try: return ImageFont.load_default(size=sz)
        except TypeError: return ImageFont.load_default()
    green=(45,235,130); white=(244,248,246); muted=(151,174,220); panel=(5,30,100)
    d.rounded_rectangle((14,14,W-14,H-14),radius=28,fill=(3,13,55),outline=(35,110,255),width=4)
    d.text((900,38),"Artic  /  MINES",font=f(31,True),fill=white)
    d.text((48,84),f"BET  {points_text(game.amount)}",font=f(22,True),fill=muted)
    # Board left: 5 x 5 tiles.
    bx,by,tile,gap=48,142,88,10
    for i in range(25):
        row,col=divmod(i,5); x=bx+col*(tile+gap); y=by+row*(tile+gap)
        opened=i in game.opened
        is_bomb=bool(game.finished and i in game.bombs)
        if is_bomb: fill=(91,24,31); outline=(235,76,83); symbol="✹"; color=(255,135,139)
        elif opened or game.finished: fill=(13,77,47); outline=(45,235,130); symbol="◆"; color=green
        else: fill=(17,35,26); outline=(36,72,51); symbol="?"; color=(122,160,137)
        d.rounded_rectangle((x,y,x+tile,y+tile),radius=13,fill=fill,outline=outline,width=3)
        box=d.textbbox((0,0),symbol,font=f(35,True)); d.text((x+(tile-(box[2]-box[0]))//2,y+(tile-(box[3]-box[1]))//2-4),symbol,font=f(35,True),fill=color)
    # Stats panel right.
    sx=610; d.rounded_rectangle((sx,142,1150,632),radius=22,fill=panel,outline=(27,76,49),width=3)
    d.text((sx+34,177),"CURRENT MULTIPLIER",font=f(22,True),fill=muted)
    mult=f"{game.multiplier:.2f}×"
    d.text((sx+32,215),mult,font=f(74,True),fill=green)
    d.line((sx+30,320,1115,320),fill=(31,68,47),width=2)
    d.text((sx+34,350),"SAFE TILES",font=f(20,True),fill=muted)
    d.text((sx+34,386),f"{len(game.opened)}",font=f(42,True),fill=white)
    d.text((sx+270,350),"MINES",font=f(20,True),fill=muted)
    d.text((sx+270,386),f"{game.mines}",font=f(42,True),fill=(255,117,122))
    d.line((sx+30,455,1115,455),fill=(31,68,47),width=2)
    payout=(game.amount*game.multiplier).quantize(Decimal("0.01"),rounding=ROUND_DOWN)
    d.text((sx+34,480),"POTENTIAL CASHOUT",font=f(20,True),fill=muted)
    d.text((sx+34,520),f"{points_text(payout)}",font=f(31,True),fill=white)
    status="GAME OVER" if game.finished else "PICK A TILE"
    d.text((48,670),status,font=f(20,True),fill=(255,115,120) if game.finished else green)
    out=io.BytesIO(); im.save(out,format="PNG",optimize=True); out.seek(0)
    return discord.File(out,filename="mines_board.png")


class MinesView(CasinoV2View):
    """Components V2 Mines board. The board and controls live inside one Container."""

    def __init__(self, game: MinesGame):
        super().__init__(timeout=300)
        self.game = game
        self.result_text = None
        self.rebuild()

    def _buttons(self):
        for child in self.walk_children():
            if isinstance(child, discord.ui.Button):
                yield child

    def rebuild(self):
        self.clear_items()

        if self.result_text:
            title, body, accent = self.result_text
        else:
            title = f"## Mines — {points_text(self.game.amount)} Bet · `{money(self.game.amount)}`"
            body = (
                f"> ﹒**{self.game.mines}** mines on a 5×5 board · more mines = bigger multiplier\n"
                f"> ﹒**{len(self.game.opened)}** safe tiles · current **{self.game.multiplier:.2f}×**"
            )
            accent = GAME_COLOR

        rows = []
        for row_index in range(5):
            row = discord.ui.ActionRow()
            for col_index in range(5):
                index = row_index * 5 + col_index
                button = discord.ui.Button(
                    label="◆",
                    style=discord.ButtonStyle.secondary,
                    custom_id=f"mine:{index}",
                    disabled=bool(self.result_text),
                )

                if self.result_text:
                    button.disabled = True
                    if index in self.game.bombs:
                        button.label = "◆"
                        button.emoji = EMOJI_LOSS
                        button.style = discord.ButtonStyle.danger
                    else:
                        button.label = "◆"
                        button.emoji = EMOJI_SAFE
                        button.style = discord.ButtonStyle.success
                elif index in self.game.opened:
                    button.label = "◆"
                    button.emoji = EMOJI_SAFE
                    button.style = discord.ButtonStyle.success
                    button.disabled = True
                else:
                    button.label = "◆"
                    button.emoji = EMOJI_SAFE
                    button.style = discord.ButtonStyle.secondary

                button.callback = self.make_callback(index)
                row.add_item(button)
            rows.append(row)

        cashout = discord.ui.Button(
            label="Cashout",
            style=discord.ButtonStyle.success,
            custom_id=f"mine_cashout:{self.game.game_id}",
            disabled=bool(self.result_text),
            emoji=EMOJI_CASHOUT,
        )
        cashout.callback = self.cashout

        avatar_url = None
        try:
            player = self.game.bot.get_user(self.game.user_id)
            if player:
                avatar_url = str(player.display_avatar.url)
        except Exception:
            pass
        title_item = (
            discord.ui.Section(discord.ui.TextDisplay(title), accessory=discord.ui.Thumbnail(avatar_url))
            if avatar_url else discord.ui.TextDisplay(title)
        )
        children = [
            title_item,
            discord.ui.TextDisplay(body),
            discord.ui.Separator(visible=True),
            discord.ui.MediaGallery(
                discord.MediaGalleryItem(media="attachment://mines_board.png")
            ),
            *rows,
            discord.ui.ActionRow(cashout),
        ]
        self.add_item(discord.ui.Container(*children, accent_color=accent))

    def set_result(self, title: str, body: str, *, won: bool):
        self.result_text = (
            title,
            body,
            0x57F287 if won else 0xED4245,
        )
        self.rebuild()

    def make_callback(self, index: int):
        async def callback(interaction: discord.Interaction):
            if interaction.user.id != self.game.user_id:
                await interaction.response.send_message(
                    "This Mines game belongs to another player.",
                    ephemeral=True,
                )
                return
            await self.game.bot.mines_click(
                interaction,
                self.game,
                index,
                self,
            )
        return callback

    async def cashout(self, interaction: discord.Interaction):
        if interaction.user.id != self.game.user_id:
            await interaction.response.send_message(
                "This Mines game belongs to another player.",
                ephemeral=True,
            )
            return
        await self.game.bot.mines_cashout(
            interaction,
            self.game,
            self,
        )

    def add_header(self):
        pass


def mines_result_v2(
    game: MinesGame,
    result_label: str,
    payout: Decimal,
    multiplier: Decimal,
):
    won = payout > 0
    net = payout - game.amount
    player = game.bot.get_user(game.user_id)
    username = player.display_name if player else "Player"
    if won:
        text = (
            f"<:Party:1557392288131584001> **WIN**\n\n"
            f"> ﹒{username} · **+{money(payout)} (`+{money(net)}` net)** at "
            f"`{multiplier:.4f}×` ﹒mines · **{game.mines} mines** · "
            f"**{len(game.opened)}** · **{multiplier:.2f}×** · stake `{money(game.amount)}`\n\n"
            f"`Bet ID {game.game_id}` · hit a big one? drop a vouch"
        )
    else:
        text = (
            f"<:BombBomb:1557392249975738448> **LOSE**\n\n"
            f"> ﹒{username} · **-{money(game.amount)} (`-{money(game.amount)}` net)** at "
            f"`{multiplier:.4f}×` ﹒mines · **{game.mines} mines** · "
            f"**{len(game.opened)}** · **{multiplier:.2f}×** · stake `{money(game.amount)}`\n\n"
            f"`Bet ID {game.game_id}` · hit a mine"
        )
    view = CasinoV2View(timeout=300)
    view.add_item(
        discord.ui.Container(
            discord.ui.TextDisplay(text),
            accent_color=0x57F287 if won else 0xED4245,
        )
    )
    return view


