async def create_balance_image(user: discord.User | discord.Member, balance) -> Optional[discord.File]:
    """Minimal Artic wallet card: large balance only, no bars or decorative rings."""
    try:
        W, H = 1200, 600
        image = Image.new("RGB", (W, H), (255, 255, 255))
        d = ImageDraw.Draw(image)
        def f(size, bold=False):
            names = ([
                "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf",
                "/usr/share/fonts/truetype/liberation2/LiberationSans-Bold.ttf",
                "/usr/share/fonts/truetype/freefont/FreeSansBold.ttf",
                "/usr/local/share/fonts/DejaVuSans-Bold.ttf",
            ] if bold else [
                "/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf",
                "/usr/share/fonts/truetype/liberation2/LiberationSans-Regular.ttf",
                "/usr/share/fonts/truetype/freefont/FreeSans.ttf",
                "/usr/local/share/fonts/DejaVuSans.ttf",
            ])
            for path in names:
                try:
                    if os.path.isfile(path): return ImageFont.truetype(path, size)
                except Exception:
                    pass
            try: return ImageFont.load_default(size=size)
            except TypeError: return ImageFont.load_default()
        green=(46, 235, 132); white=(245, 250, 247); muted=(159, 190, 172)
        d.rounded_rectangle((16,16,W-16,H-16), radius=30, fill=(4,20,13), outline=(35,155,89), width=4)
        d.text((64,55), "Artic", font=f(38, True), fill=green)
        d.text((64,130), f"{user.display_name}"[:28], font=f(34, True), fill=muted)
        d.text((64,215), "BALANCE", font=f(30, True), fill=green)
        usd_balance = D(balance).quantize(Decimal("0.01"), rounding=ROUND_DOWN)
        pts = f"${usd_balance:,.2f}"
        amount_font=f(112, True)
        box=d.textbbox((0,0), pts, font=amount_font)
        if box[2]-box[0] > W-130:
            amount_font=f(82, True); box=d.textbbox((0,0), pts, font=amount_font)
        d.text(((W-(box[2]-box[0]))//2, 260), pts, font=amount_font, fill=white)
        usd=f"{money(balance)} USD  ·  All amounts in USD"
        box=d.textbbox((0,0),usd,font=f(27, True))
        d.text(((W-(box[2]-box[0]))//2, 425), usd, font=f(27, True), fill=muted)
        out=io.BytesIO(); image.save(out, format="PNG", optimize=True); out.seek(0)
        return discord.File(out, filename="balance.png")
    except Exception as exc:
        print(f"[BALANCE] image error: {exc}")
        return None


