    await interaction.response.send_message(
        embed=base_embed(
            title="Wallet",
            description=(
                f"**Balance:** {money(balance)}"
            ),
        ),
        view=WalletView(
            bot,
            interaction.user.id,
        ),
        ephemeral=False,
    )

