@prefix_command(name="reset", aliases=["lbreset"])
@bot_owner_only()
async def reset_database_command(interaction: PrefixInteraction):
    """Destructively reset all application data while preserving the database schema."""
    if not await require_database(interaction):
        return

    try:
        async with bot.db.pool.acquire() as conn:
            async with conn.transaction():
                tables = await conn.fetch("""
                    SELECT tablename
                    FROM pg_tables
                    WHERE schemaname = 'public'
                """)
                names = [str(row["tablename"]) for row in tables]
                if names:
                    quoted = ", ".join('"' + name.replace('"', '""') + '"' for name in names)
                    await conn.execute(f"TRUNCATE TABLE {quoted} RESTART IDENTITY CASCADE")

                # Restore the house row so the bot has a valid house record after reset.
                await conn.execute("""
                    INSERT INTO house(id, balance, ltc_balance, sol_balance, usdt_balance)
                    VALUES(1, 87.00, 52.20, 26.10, 8.70)
                    ON CONFLICT(id) DO UPDATE SET
                        balance=EXCLUDED.balance,
                        ltc_balance=EXCLUDED.ltc_balance,
                        sol_balance=EXCLUDED.sol_balance,
                        usdt_balance=EXCLUDED.usdt_balance
                """)

        # Reset in-memory state as well.
        bot.disabled_commands.clear()
        bot.min_withdrawal = MIN_WITHDRAWAL
        bot.voucher_channel_id = None
        if hasattr(bot, "withdraw_admin_channel_id"):
            bot.withdraw_admin_channel_id = 0
        if hasattr(bot, "withdraw_log_channel_id"):
            bot.withdraw_log_channel_id = 0
        if hasattr(bot, "live_games"):
            bot.live_games.clear()
        if hasattr(bot, "active_games"):
            bot.active_games.clear()

        await interaction.response.send_message(
            embed=success_embed(
                "Database Reset",
                "The entire application database has been reset. All users, balances, game history, withdrawals, deposits, settings, promo data and other stored records were cleared."
            )
        )
    except Exception as exc:
        await interaction.response.send_message(
            embed=error_embed("Reset Failed", f"The database could not be reset: `{type(exc).__name__}`")
        )


