# RAIN
# ============================================================

async def join_rain(
    self: CasinoBot,
    interaction: discord.Interaction,
    rain_id: str,
):

    rain = self.active_rains.get(
        rain_id
    )

    if not rain:

        await interaction.response.send_message(
            "This rain has already ended.",
            ephemeral=True,
        )

        return

    # --------------------------------------------------------
    # OWNER CANNOT JOIN OWN RAIN
    # --------------------------------------------------------

    if interaction.user.id == rain["user_id"]:

        await interaction.response.send_message(
            "You cannot join your own rain.",
            ephemeral=True,
        )

        return

    # --------------------------------------------------------
    # ALREADY JOINED
    # --------------------------------------------------------

    if interaction.user.id in rain["players"]:

        await interaction.response.send_message(
            "You already joined this rain.",
            ephemeral=True,
        )

        return

    # --------------------------------------------------------
    # JOIN
    # --------------------------------------------------------

    rain["players"].add(
        interaction.user.id
    )

    await interaction.response.send_message(
        "You joined the rain.",
        ephemeral=True,
    )


CasinoBot.join_rain = join_rain


async def finish_rain(
    self: CasinoBot,
    rain_id: str,
):

    # --------------------------------------------------------
    # REMOVE FROM ACTIVE RAINS
    # --------------------------------------------------------

    rain = self.active_rains.pop(
        rain_id,
        None,
    )

    if not rain:
        return

    amount = D(
        rain["amount"]
    )

    players = list(
        rain["players"]
    )

    # --------------------------------------------------------
    # GET CHANNEL
    # --------------------------------------------------------

    channel = self.get_channel(
        rain["channel_id"]
    )

    if not channel:

        try:

            await self.db.change_balance(
                rain["user_id"],
                amount,
                kind="rain_refund",
                note=rain_id,
            )

        except Exception as e:

            print(
                f"[RAIN] Refund error: {e}"
            )

        return

    # --------------------------------------------------------
    # NOBODY JOINED
    # --------------------------------------------------------

    if not players:

        try:

            await self.db.change_balance(
                rain["user_id"],
                amount,
                kind="rain_refund",
                note=rain_id,
            )

            await channel.send(
                f"## Rain Ended — {money(amount)}\n"
                "Nobody joined the rain, so the full "
                "amount was refunded."
            )

        except Exception as e:

            print(
                f"[RAIN] Refund error: {e}"
            )

            await channel.send(
                "## Rain Ended\n"
                "Nobody joined the rain."
            )

        return

    # --------------------------------------------------------
    # CALCULATE SHARE
    # --------------------------------------------------------

    player_count = len(players)

    share = (
        amount
        / Decimal(player_count)
    ).quantize(
        Decimal("0.01"),
        rounding=ROUND_DOWN,
    )

    if share <= Decimal("0"):

        await self.db.change_balance(
            rain["user_id"],
            amount,
            kind="rain_refund",
            note=rain_id,
        )

        await channel.send(
            f"## Rain Ended — {money(amount)}\n"
            "The amount was too small to distribute "
            "between the players, so it was refunded."
        )

        return

    # --------------------------------------------------------
    # PAY PLAYERS
    # --------------------------------------------------------

    successful = []
    failed = []

    for user_id in players:

        try:

            credited = await self.db.change_balance(
                user_id,
                share,
                kind="rain",
                note=rain_id,
            )

            if credited:

                successful.append(
                    user_id
                )

            else:

                failed.append(
                    user_id
                )

        except Exception as e:

            print(
                f"[RAIN] Failed to credit {user_id}: {e}"
            )

            failed.append(
                user_id
            )

    # --------------------------------------------------------
    # NOBODY COULD BE CREDITED
    # --------------------------------------------------------

    if not successful:

        try:

            await self.db.change_balance(
                rain["user_id"],
                amount,
                kind="rain_refund",
                note=rain_id,
            )

        except Exception as e:

            print(
                f"[RAIN] Refund error: {e}"
            )

        await channel.send(
            f"## Rain Ended — {money(amount)}\n"
            "Nobody could be credited, so the rain "
            "was refunded."
        )

        return

    # --------------------------------------------------------
    # CALCULATE UNUSED AMOUNT
    # --------------------------------------------------------

    distributed = (
        share
        * Decimal(len(successful))
    )

    remainder = (
        amount
        - distributed
    ).quantize(
        Decimal("0.01"),
        rounding=ROUND_DOWN,
    )

    # --------------------------------------------------------
    # RETURN FAILED PLAYER SHARES + ROUNDING REMAINDER
    # TO THE RAIN OWNER
    # --------------------------------------------------------

    if failed:

        failed_amount = (
            share
            * Decimal(len(failed))
        )

        remainder += failed_amount

    if remainder > Decimal("0"):

        try:

            await self.db.change_balance(
                rain["user_id"],
                remainder,
                kind="rain_remainder_refund",
                note=rain_id,
            )

        except Exception as e:

            print(
                f"[RAIN] Remainder refund error: {e}"
            )

    # --------------------------------------------------------
    # PLAYER MENTIONS
    # --------------------------------------------------------

    mention_text = " ".join(
        f"<@{user_id}>"
        for user_id in successful
    )

    # --------------------------------------------------------
    # RESULT
    # --------------------------------------------------------

    await channel.send(
        f"## Rain Ended — {money(amount)}\n"
        f"## **{rain['owner_mention']}** rained on "
        f"**{len(successful)}** players!\n\n"
        f"**{money(share)}** each\n\n"
        f"{mention_text}"
    )


CasinoBot.finish_rain = finish_rain


