COINFLIP_MULTIPLIER = Decimal("1.96")


# ============================================================
# COINFLIP RESULT IMAGE
# ============================================================

def generate_coinflip_result_image(
    username: str,
    bet: Decimal,
    choice: str,
    result: str,
    won: bool,
):
    import io
    import math

    from PIL import (
        Image,
        ImageDraw,
        ImageFont,
        ImageFilter,
    )

    # ========================================================
    # IMAGE SIZE
    # ========================================================

    WIDTH = 1600
    HEIGHT = 1200

    image = Image.new(
        "RGBA",
        (WIDTH, HEIGHT),
        (5, 6, 14, 255),
    )

    draw = ImageDraw.Draw(image)

    # ========================================================
    # FONTS
    # ========================================================

    def load_font(size, bold=False):

        if bold:
            paths = [
                "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf",
                "/usr/share/fonts/truetype/liberation2/LiberationSans-Bold.ttf",
                "/usr/share/fonts/truetype/freefont/FreeSansBold.ttf",
                "C:/Windows/Fonts/arialbd.ttf",
                "C:/Windows/Fonts/segoeuib.ttf",
            ]
        else:
            paths = [
                "/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf",
                "/usr/share/fonts/truetype/liberation2/LiberationSans-Regular.ttf",
                "/usr/share/fonts/truetype/freefont/FreeSans.ttf",
                "C:/Windows/Fonts/arial.ttf",
                "C:/Windows/Fonts/segoeui.ttf",
            ]

        for path in paths:
            try:
                return ImageFont.truetype(path, size)
            except Exception:
                continue

        return ImageFont.load_default()

    font_user = load_font(48, True)
    font_bet = load_font(56, True)
    font_result = load_font(82, True)
    font_landed = load_font(40, True)

    # Large coin text
    font_coin = load_font(105, True)

    # ========================================================
    # BACKGROUND
    # ========================================================

    for y in range(HEIGHT):

        ratio = y / HEIGHT

        r = int(5 + ratio * 4)
        g = int(6 + ratio * 5)
        b = int(14 + ratio * 10)

        draw.line(
            [(0, y), (WIDTH, y)],
            fill=(r, g, b, 255),
        )

    # ========================================================
    # DIAGONAL LINES
    # ========================================================

    line_layer = Image.new(
        "RGBA",
        (WIDTH, HEIGHT),
        (0, 0, 0, 0),
    )

    line_draw = ImageDraw.Draw(
        line_layer
    )

    for offset in range(
        -HEIGHT,
        WIDTH,
        60,
    ):

        line_draw.line(
            [
                (offset, 0),
                (offset + HEIGHT, HEIGHT),
            ],
            fill=(70, 75, 110, 40),
            width=2,
        )

    image.alpha_composite(
        line_layer
    )

    draw = ImageDraw.Draw(image)

    # ========================================================
    # CENTER
    # ========================================================

    center_x = WIDTH // 2
    center_y = 600

    # ========================================================
    # HEXAGON
    # ========================================================

    hex_radius = 520

    def hex_points(radius):

        points = []

        for i in range(6):

            angle = math.radians(
                (60 * i) - 30
            )

            x = (
                center_x
                + radius * math.cos(angle)
            )

            y = (
                center_y
                + radius * math.sin(angle)
            )

            points.append(
                (x, y)
            )

        return points

    outer_hex = hex_points(
        hex_radius
    )

    # ========================================================
    # HEXAGON GLOW
    # ========================================================

    glow = Image.new(
        "RGBA",
        (WIDTH, HEIGHT),
        (0, 0, 0, 0),
    )

    glow_draw = ImageDraw.Draw(
        glow
    )

    for size in range(
        70,
        0,
        -2,
    ):

        points = hex_points(
            hex_radius + size
        )

        alpha = max(
            5,
            int(100 - size * 1.3),
        )

        glow_draw.line(
            points + [points[0]],
            fill=(
                255,
                255,
                255,
                alpha,
            ),
            width=10,
            joint="curve",
        )

    glow = glow.filter(
        ImageFilter.GaussianBlur(15)
    )

    image.alpha_composite(
        glow
    )

    draw = ImageDraw.Draw(image)

    # ========================================================
    # HEXAGON FILL
    # ========================================================

    draw.polygon(
        outer_hex,
        fill=(10, 12, 24, 250),
    )

    # ========================================================
    # HEXAGON BORDER
    # ========================================================

    draw.line(
        outer_hex + [outer_hex[0]],
        fill=(
            255,
            255,
            255,
            255,
        ),
        width=7,
        joint="curve",
    )

    inner_hex = hex_points(
        hex_radius - 14
    )

    draw.line(
        inner_hex + [inner_hex[0]],
        fill=(
            255,
            255,
            255,
            210,
        ),
        width=4,
        joint="curve",
    )

    # ========================================================
    # CENTERED TEXT
    # ========================================================

    def centered_text(
        text,
        y,
        font,
        fill,
    ):

        bbox = draw.textbbox(
            (0, 0),
            text,
            font=font,
        )

        text_width = (
            bbox[2] - bbox[0]
        )

        draw.text(
            (
                center_x - text_width / 2,
                y,
            ),
            text,
            font=font,
            fill=fill,
        )

    # ========================================================
    # USERNAME
    # ========================================================

    safe_username = str(
        username
    ).strip()

    if len(safe_username) > 26:

        safe_username = (
            safe_username[:23]
            + "..."
        )

    choice_text = str(
        choice
    ).upper()

    centered_text(
        f"@{safe_username} BETTED",
        105,
        font_user,
        (
            255,
            255,
            255,
            255,
        ),
    )

    centered_text(
        f"{money(bet)} ON {choice_text}",
        165,
        font_bet,
        (
            255,
            255,
            255,
            255,
        ),
    )

    # ========================================================
    # COIN POSITION
    # ========================================================

    coin_x = center_x
    coin_y = 565

    # BIG COIN
    coin_radius = 285

    # ========================================================
    # DETERMINE COIN SIDE
    # ========================================================

    result_lower = str(
        result
    ).strip().lower()

    if result_lower in (
        "heads",
        "head",
        "h",
    ):

        coin_color = (
            92,
            88,
            165,
            255,
        )

        coin_dark = (
            70,
            67,
            135,
            255,
        )

        coin_border = (
            180,
            175,
            230,
            255,
        )

        coin_text = "HEADS"

        glow_color = (
            125,
            120,
            255,
        )

    else:

        coin_color = (
            240,
            65,
            145,
            255,
        )

        coin_dark = (
            205,
            45,
            115,
            255,
        )

        coin_border = (
            255,
            150,
            205,
            255,
        )

        coin_text = "TAILS"

        glow_color = (
            255,
            75,
            165,
        )

    # ========================================================
    # COIN GLOW
    # ========================================================

    coin_glow = Image.new(
        "RGBA",
        (WIDTH, HEIGHT),
        (0, 0, 0, 0),
    )

    coin_glow_draw = ImageDraw.Draw(
        coin_glow
    )

    for extra in range(
        100,
        0,
        -4,
    ):

        alpha = max(
            5,
            int(110 - extra),
        )

        coin_glow_draw.ellipse(
            (
                coin_x
                - coin_radius
                - extra,

                coin_y
                - coin_radius
                - extra,

                coin_x
                + coin_radius
                + extra,

                coin_y
                + coin_radius
                + extra,
            ),
            outline=(
                glow_color[0],
                glow_color[1],
                glow_color[2],
                alpha,
            ),
            width=12,
        )

    coin_glow = coin_glow.filter(
        ImageFilter.GaussianBlur(20)
    )

    image.alpha_composite(
        coin_glow
    )

    draw = ImageDraw.Draw(image)

    # ========================================================
    # COIN SHADOW
    # ========================================================

    shadow = Image.new(
        "RGBA",
        (WIDTH, HEIGHT),
        (0, 0, 0, 0),
    )

    shadow_draw = ImageDraw.Draw(
        shadow
    )

    shadow_draw.ellipse(
        (
            coin_x - coin_radius + 35,
            coin_y - coin_radius + 45,
            coin_x + coin_radius + 45,
            coin_y + coin_radius + 65,
        ),
        fill=(
            0,
            0,
            0,
            230,
        ),
    )

    shadow = shadow.filter(
        ImageFilter.GaussianBlur(25)
    )

    image.alpha_composite(
        shadow
    )

    draw = ImageDraw.Draw(image)

    # ========================================================
    # OUTER COIN
    # ========================================================

    draw.ellipse(
        (
            coin_x - coin_radius,
            coin_y - coin_radius,
            coin_x + coin_radius,
            coin_y + coin_radius,
        ),
        fill=coin_border,
        outline=(
            255,
            255,
            255,
            255,
        ),
        width=8,
    )

    # ========================================================
    # COIN MAIN BODY
    # ========================================================

    edge = coin_radius - 12

    draw.ellipse(
        (
            coin_x - edge,
            coin_y - edge,
            coin_x + edge,
            coin_y + edge,
        ),
        fill=coin_dark,
        outline=(
            255,
            255,
            255,
            90,
        ),
        width=4,
    )

    # ========================================================
    # COIN FACE
    # ========================================================

    face = coin_radius - 25

    draw.ellipse(
        (
            coin_x - face,
            coin_y - face,
            coin_x + face,
            coin_y + face,
        ),
        fill=coin_color,
        outline=(
            255,
            255,
            255,
            130,
        ),
        width=5,
    )

    # ========================================================
    # INNER COIN BORDER
    # ========================================================

    inner = coin_radius - 42

    draw.ellipse(
        (
            coin_x - inner,
            coin_y - inner,
            coin_x + inner,
            coin_y + inner,
        ),
        outline=(
            255,
            255,
            255,
            100,
        ),
        width=4,
    )

    # ========================================================
    # COIN TEXT
    # ========================================================

    bbox = draw.textbbox(
        (0, 0),
        coin_text,
        font=font_coin,
    )

    text_width = (
        bbox[2] - bbox[0]
    )

    text_height = (
        bbox[3] - bbox[1]
    )

    text_x = (
        coin_x
        - text_width / 2
    )

    text_y = (
        coin_y
        - text_height / 2
        - 10
    )

    # --------------------------------------------------------
    # TEXT SHADOW
    # --------------------------------------------------------

    draw.text(
        (
            text_x + 7,
            text_y + 9,
        ),
        coin_text,
        font=font_coin,
        fill=(
            40,
            20,
            40,
            180,
        ),
    )

    # --------------------------------------------------------
    # WHITE TEXT
    # --------------------------------------------------------

    draw.text(
        (
            text_x,
            text_y,
        ),
        coin_text,
        font=font_coin,
        fill=(
            255,
            255,
            255,
            255,
        ),
    )

    # ========================================================
    # COIN TOP HIGHLIGHT
    # ========================================================

    draw.arc(
        (
            coin_x - face + 15,
            coin_y - face + 15,
            coin_x + face - 15,
            coin_y + face - 15,
        ),
        200,
        320,
        fill=(
            255,
            255,
            255,
            170,
        ),
        width=8,
    )

    # ========================================================
    # YOU WON / YOU LOST
    # ========================================================

    if won:

        result_text = "YOU WON"

        result_color = (
            80,
            255,
            150,
            255,
        )

    else:

        result_text = "YOU LOST"

        result_color = (
            255,
            75,
            95,
            255,
        )

    centered_text(
        result_text,
        850,
        font_result,
        result_color,
    )

    # ========================================================
    # LANDED ON
    # ========================================================

    centered_text(
        f"LANDED ON {coin_text}",
        955,
        font_landed,
        (
            255,
            255,
            255,
            235,
        ),
    )

    # ========================================================
    # WIN / LOSS AMOUNT
    # ========================================================

    if won:

        bottom_text = (
            f"You won "
            f"{money(bet * COINFLIP_MULTIPLIER)}"
        )

        bottom_color = (
            90,
            255,
            155,
            255,
        )

    else:

        bottom_text = (
            f"You lost "
            f"{money(bet)}"
        )

        bottom_color = (
            255,
            90,
            110,
            255,
        )

    centered_text(
        bottom_text,
        1015,
        font_landed,
        bottom_color,
    )

    # ========================================================
    # EXPORT
    # ========================================================

    buffer = io.BytesIO()

    image.save(
        buffer,
        format="PNG",
        optimize=True,
    )

    buffer.seek(0)

    return buffer


# ============================================================
# COINFLIP COMMAND
# ============================================================

class CoinflipLobbyView(CasinoV2View):
    def __init__(self, ctx, amount):
        super().__init__(timeout=180)
        self.ctx = ctx
        self.amount = amount
        self._build()

    def _build(self):
        heads = discord.ui.Button(label="Heads", style=discord.ButtonStyle.primary, custom_id="cf_heads")
        tails = discord.ui.Button(label="Tails", style=discord.ButtonStyle.secondary, custom_id="cf_tails")
        heads.callback = self.pick_heads
        tails.callback = self.pick_tails
        self.add_item(discord.ui.Container(
            discord.ui.TextDisplay("## Coinflip — demo"),
            discord.ui.TextDisplay(f"> ﹒pick a side · win pays ≈ **{COINFLIP_MULTIPLIER:.2f}×**\n> ﹒bet **{money(self.amount)}**"),
            discord.ui.Separator(visible=True),
            discord.ui.MediaGallery(discord.MediaGalleryItem(media="attachment://casino_divider.png")),
            discord.ui.MediaGallery(
                discord.MediaGalleryItem(media=COINFLIP_HEADS_IMAGE_URL),
                discord.MediaGalleryItem(media=COINFLIP_TAILS_IMAGE_URL),
            ),
            discord.ui.ActionRow(heads, tails),
            accent_color=0x5865F2,
        ))

    async def _pick(self, interaction, choice):
        if interaction.user.id != self.ctx.author.id:
            await interaction.response.send_message("This Coinflip menu belongs to another player.", ephemeral=True)
            return
        await interaction.response.defer()
        try:
            await interaction.message.delete()
        except Exception:
            pass
        await coinflip(self.ctx, str(self.amount), choice)

    async def pick_heads(self, interaction):
        await self._pick(interaction, "heads")

    async def pick_tails(self, interaction):
        await self._pick(interaction, "tails")


@prefix_command(
    name="coinflip",
    aliases=["cf"],
)
async def coinflip(
    ctx,
    amount: str,
    choice: str = "",
):

    # ========================================================
    # USER
    # ========================================================

    user = ctx.author
    user_id = user.id

    # No choice supplied: show the new Components V2 selector.
    if not str(choice).strip():
        balance = await bot.get_balance(user_id)
        bet_preview = usd_from_points_input(amount, balance)
        if bet_preview is None or bet_preview < MIN_BET:
            await ctx.send(embed=error_embed("Invalid Amount", f"Minimum bet is **{money(MIN_BET)}**."))
            return
        divider = _divider_file()
        kwargs = {"view": CoinflipLobbyView(ctx, bet_preview)}
        if divider:
            kwargs["file"] = divider
        await ctx.send(**kwargs)
        return

    # ========================================================
    # NORMALIZE CHOICE
    # ========================================================

    choice = (
        str(choice)
        .strip()
        .lower()
    )

    choice_aliases = {
        "h": "heads",
        "head": "heads",
        "heads": "heads",

        "t": "tails",
        "tail": "tails",
        "tails": "tails",
    }

    choice = choice_aliases.get(
        choice
    )

    if choice is None:

        await ctx.send(
            embed=error_embed(
                "Invalid Choice",
                (
                    "Choose either **heads** "
                    "or **tails**.\n\n"
                    "Examples:\n"
                    "`.cf 1 heads`\n"
                    "`.cf 1 tails`"
                ),
            )
        )

        return

    selected_name = (
        "Heads"
        if choice == "heads"
        else "Tails"
    )

    # ========================================================
    # COOLDOWN
    # ========================================================

    cooldown = bot.check_game_cooldown(
        user_id,
        "coinflip",
    )

    if cooldown:

        await ctx.send(
            embed=error_embed(
                "Cooldown",
                (
                    f"Please wait **{cooldown:.1f}s** "
                    "before playing again."
                ),
            )
        )

        return

    # ========================================================
    # BALANCE
    # ========================================================

    balance = await bot.get_balance(
        user_id
    )

    bet = usd_from_points_input(
        amount,
        balance,
    )

    if bet is None:

        await ctx.send(
            embed=error_embed(
                "Invalid Amount",
                (
                    "Enter a valid amount.\n\n"
                    "Examples:\n"
                    "`.cf 1 heads`\n"
                    "`.cf 0.50 tails`\n"
                    "`.cf all heads`"
                ),
            )
        )

        return

    bet = Decimal(str(bet))

    # ========================================================
    # MINIMUM BET
    # ========================================================

    if bet < MIN_BET:

        await ctx.send(
            embed=error_embed(
                "Minimum Bet",
                (
                    f"The minimum bet is "
                    f"**{money(MIN_BET)}**."
                ),
            )
        )

        return

    # ========================================================
    # BALANCE CHECK
    # ========================================================

    if bet > balance:

        await ctx.send(
            embed=error_embed(
                "Insufficient Balance",
                (
                    "You don't have enough balance "
                    "for this bet."
                ),
            )
        )

        return

    # ========================================================
    # GAME DATA
    # ========================================================

    game_id = bot.next_game_id()

    server_seed = (
        bot.create_server_seed()
    )

    server_hash = (
        bot.server_hash(
            server_seed
        )
    )

    client_seed = (
        bot.create_client_seed(
            user_id
        )
    )

    nonce = 0

    # ========================================================
    # DEDUCT BET
    # ========================================================

    deducted = await bot.deduct_bet(
        user_id,
        bet,
        "coinflip",
    )

    if not deducted:

        await ctx.send(
            embed=error_embed(
                "Bet Failed",
                (
                    "Your balance changed "
                    "before the bet could be placed. "
                    "Please try again."
                ),
            )
        )

        return

    # ========================================================
    # ACTIVE GAME
    # ========================================================

    bot.register_fair_game(
        user_id, "coinflip", game_id, server_seed, client_seed, nonce,
        "50.00%", f"Selected side: {choice}"
    )

    bot.active_games[user_id] = {
        "type": "coinflip",
        "game_id": game_id,
        "bet": bet,
        "selected": choice,
        "server_seed": server_seed,
        "server_hash": server_hash,
        "client_seed": client_seed,
        "nonce": nonce,
    }

    # ========================================================
    # FLIPPING MESSAGE
    # ========================================================

    flipping_view = CasinoV2View(timeout=30)
    flipping_view.add_item(discord.ui.Container(
        discord.ui.TextDisplay("## Coinflip — Flipping"),
        discord.ui.TextDisplay(f"> ﹒{user.display_name} · **{money(bet)}** on **{selected_name}**\n> ﹒game `#{game_id}`"),
        accent_color=0x5865F2,
    ))
    flipping_message = await ctx.send(view=flipping_view)

    # ========================================================
    # FLIP DELAY
    # ========================================================

    await asyncio.sleep(2)

    # ========================================================
    # GET ACTIVE GAME
    # ========================================================

    game = bot.active_games.pop(
        user_id,
        None,
    )

    if not game:

        try:

            await bot.settle_win(
                user_id,
                bet,
                bet,
                "coinflip_recovery",
            )

        except Exception:
            pass

        await flipping_message.edit(
            embed=error_embed(
                "Game Error",
                (
                    "The game state could not be found. "
                    "Your bet was protected from being lost."
                ),
            )
        )

        return

    # ========================================================
    # PROVABLY FAIR ROLL
    # ========================================================

    try:

        roll = bot.fair_roll(
            game["server_seed"],
            game["client_seed"],
            game["nonce"],
            "coinflip",
        )

    except Exception:

        try:

            await bot.settle_win(
                user_id,
                bet,
                bet,
                "coinflip_recovery",
            )

        except Exception:
            pass

        await flipping_message.edit(
            embed=error_embed(
                "Game Error",
                (
                    "The fair result could not be generated. "
                    "Your bet was refunded."
                ),
            )
        )

        return

    # ========================================================
    # RESULT
    # ========================================================

    result = (
        "heads"
        if roll < Decimal("50")
        else "tails"
    )

    won = (
        result == choice
    )

    # ========================================================
    # SETTLEMENT
    # ========================================================

    try:

        if won:

            payout = (
                bet * COINFLIP_MULTIPLIER
            ).quantize(
                Decimal("0.01"),
                rounding=ROUND_DOWN,
            )

            await bot.settle_win(
                user_id,
                bet,
                payout,
                "coinflip",
            )

        else:

            payout = Decimal("0")

            await bot.settle_loss(
                user_id,
                bet,
                "coinflip",
            )

    except Exception:

        await flipping_message.edit(
            embed=error_embed(
                "Game Error",
                (
                    "The result was generated, "
                    "but the balance settlement failed. "
                    "Please contact an administrator."
                ),
            )
        )

        return

    # ========================================================
    # GENERATE IMAGE
    # ========================================================

    try:

        image_buffer = (
            generate_coinflip_result_image(
                username=user.display_name,
                bet=bet,
                choice=selected_name,
                result=result,
                won=won,
            )
        )

    except Exception:

        await flipping_message.edit(
            embed=error_embed(
                "Image Error",
                (
                    "The game finished successfully, "
                    "but the result image could not "
                    "be generated."
                ),
            )
        )

        return

    # ========================================================
    # DISCORD FILE
    # ========================================================

    image_file = discord.File(
        image_buffer,
        filename="coinflip_result.png",
    )

    # ========================================================
    # COMPONENTS V2 RESULT
    # ========================================================

    result_title = "## Coinflip — WIN" if won else "## Coinflip — LOSE"
    result_body = (
        f"> ﹒**{user.display_name}** · **{money(bet)}** on **{selected_name}**\n"
        f"> ﹒landed on **{result.title()}** · {'+' if won else '-'}{money(payout if won else bet)}\n\n"
        f"**Bet ID:** `#{game_id}`\n"
        f"**Payout:** `{money(payout)}` · **{COINFLIP_MULTIPLIER:.2f}×**\n"
        f"-# Verify this result with `.verify {game_id}`"
    )
    result_view = CasinoV2View(timeout=300)
    result_view.add_item(discord.ui.Container(
        discord.ui.TextDisplay(result_title),
        discord.ui.TextDisplay(result_body),
        discord.ui.Separator(visible=True),
        discord.ui.MediaGallery(discord.MediaGalleryItem(media=COINFLIP_HEADS_IMAGE_URL if result == "heads" else COINFLIP_TAILS_IMAGE_URL)),
        discord.ui.TextDisplay(
            f"-# Provably fair · server hash `{game['server_hash']}` · client seed `{game['client_seed']}` · nonce `{game['nonce']}`"
        ),
        accent_color=0x57F287 if won else 0xED4245,
    ))

    await flipping_message.edit(
        embed=None,
        view=result_view,
        attachments=[],
    )

# ============================================================
# MINES
# ============================================================

def mines_multiplier(
    mines: int,
    opened: int,
) -> Decimal:

    if opened <= 0:
        return Decimal("1.00")

    safe_tiles = 25 - mines

    multiplier = (
        Decimal("25")
        / Decimal(str(safe_tiles))
    ) ** opened

    multiplier *= Decimal("0.96")

    return multiplier.quantize(
        Decimal("0.01"),
        rounding=ROUND_DOWN,
    )


def mines_embed(
    game: MinesGame,
) -> discord.Embed:

    current = mines_multiplier(
        game.mines,
        len(game.opened),
    )

    payout = (
        game.amount * current
    ).quantize(
        Decimal("0.01"),
        rounding=ROUND_DOWN,
    )

    embed = base_embed(
        title="## Mines",
        description=(
            f"**Bet:** {money(game.amount)}\n"
            f"**Mines:** {game.mines}\n"
            f"**Opened:** {len(game.opened)}/"
            f"{24 - game.mines}\n"
            f"**Multiplier:** {current:.2f}x\n"
            f"**Current Payout:** {money(payout)}"
        ),
        color=0x00E676,
    )

    embed.add_field(
        name="Game",
        value=f"`#{game.game_id}`",
        inline=True,
    )

    embed.add_field(
        name="Provably Fair",
        value=(
            f"Server Hash: `{game.server_hash}`"
        ),
        inline=False,
    )

    return embed

# ============================================================
# MINES CLICK
# ============================================================

async def mines_click(
    self,
    interaction: discord.Interaction,
    game: MinesGame,
    index: int,
    view: MinesView,
):

    if game.finished:

        await interaction.response.send_message(
            "This Mines game has ended.",
            ephemeral=False,
        )
        return

    if index in game.opened:

        await interaction.response.send_message(
            "That tile is already open.",
            ephemeral=False,
        )
        return

    game.opened.add(index)

    button = next(
        (
            item
            for item in view.children
            if getattr(
                item,
                "custom_id",
                None,
            ) == f"mine:{index}"
        ),
        None,
    )

    if index in game.bombs:

        game.finished = True

        for item in view.children:

            custom_id = getattr(
                item,
                "custom_id",
                "",
            )

            if (
                custom_id.startswith(
                    "mine:"
                )
            ):

                tile_index = int(
                    custom_id.split(":")[1]
                )

                item.disabled = True

                if tile_index in game.bombs:
                    item.label = "◆"
                    item.emoji = EMOJI_LOSS
                    item.style = (
                        discord.ButtonStyle.danger
                    )

                elif tile_index in game.opened:
                    item.label = "◆"
                    item.emoji = EMOJI_SAFE
                    item.style = (
                        discord.ButtonStyle.success
                    )

        await bot.settle_loss(
            game.user_id,
            game.amount,
            "mines",
        )

        embed = base_embed(
            title="Mines — Bomb!",
            description=(
                f"You hit a bomb.\n\n"
                f"**Bet:** {money(game.amount)}\n"
                f"**Lost:** {money(game.amount)}"
            ),
            color=0xED4245,
        )

        embed.add_field(
            name="Game",
            value=f"`#{game.game_id}`",
            inline=True,
        )

        embed.add_field(
            name="Server Hash",
            value=f"`{game.server_hash}`",
            inline=False,
        )

        bot.active_mines.pop(
            game.user_id,
            None,
        )

        view.set_result("Mines — Bomb!", f"You hit a bomb. Bet: {money(game.amount)} · Lost: {money(game.amount)} · Game #{game.game_id}", won=False)
        board_file = create_mines_board_image(game)
        await interaction.response.edit_message(
            content=None, embed=None, view=view, attachments=[board_file],
        )

        return

    if button:

        button.label = "◆"
        button.emoji = EMOJI_SAFE
        button.style = (
            discord.ButtonStyle.success
        )
        button.disabled = True

    safe_tiles = 24 - game.mines

    if len(game.opened) >= safe_tiles:

        await mines_cashout(
            self,
            interaction,
            game,
            view,
            automatic=True,
        )

        return

    view.rebuild()
    board_file = create_mines_board_image(game)
    await interaction.response.edit_message(
        content=None, embed=None, view=view, attachments=[board_file],
    )


# ============================================================
# MINES CASHOUT
# ============================================================

async def mines_cashout(
    self,
    interaction: discord.Interaction,
    game: MinesGame,
    view: MinesView,
    automatic: bool = False,
):

    if game.finished:

        await interaction.response.send_message(
            "This Mines game has already ended.",
            ephemeral=False,
        )
        return

    if len(game.opened) <= 0:

        await interaction.response.send_message(
            "Open at least one tile before cashing out.",
            ephemeral=False,
        )
        return

    game.finished = True

    multiplier = mines_multiplier(
        game.mines,
        len(game.opened),
    )

    payout = (
        game.amount * multiplier
    ).quantize(
        Decimal("0.01"),
        rounding=ROUND_DOWN,
    )

    await bot.settle_win(
        game.user_id,
        game.amount,
        payout,
        "mines",
    )

    for item in view.children:

        custom_id = getattr(
            item,
            "custom_id",
            "",
        )

        if custom_id.startswith("mine:"):

            tile_index = int(
                custom_id.split(":")[1]
            )

            item.disabled = True

            if tile_index in game.bombs:
                item.label = "◆"
                item.emoji = EMOJI_LOSS
                item.style = (
                    discord.ButtonStyle.danger
                )

            elif tile_index in game.opened:
                item.label = "◆"
                item.emoji = EMOJI_SAFE
                item.style = (
                    discord.ButtonStyle.success
                )

    bot.active_mines.pop(
        game.user_id,
        None,
    )

    embed = base_embed(
        title=" Mines — Cashed Out",
        description=(
            f"**Bet:** {money(game.amount)}\n"
            f"**Multiplier:** {multiplier:.2f}x\n"
            f"**Payout:** {money(payout)}"
        ),
        color=0x57F287,
    )

    embed.add_field(
        name="Tiles Opened",
        value=str(len(game.opened)),
        inline=True,
    )

    embed.add_field(
        name="Game",
        value=f"`#{game.game_id}`",
        inline=True,
    )

    embed.add_field(
        name="Provably Fair",
        value=(
            f"Server Hash: `{game.server_hash}`\n"
            f"Client Seed: `{game.client_seed}`\n"
            f"Nonce: `{game.nonce}`"
        ),
        inline=False,
    )

    if automatic:

        embed.title = " Mines — All Safe Tiles!"

    view.set_result("Mines — Cashed Out", f"Cashout at {multiplier:.2f}× · Payout {money(payout)} · Game #{game.game_id}", won=True)
    board_file = create_mines_board_image(game)
    await interaction.response.edit_message(content=None, embed=None, view=view, attachments=[board_file])


# Attach the methods to the bot instance.
CasinoBot.mines_click = mines_click
CasinoBot.mines_cashout = mines_cashout

