class BlackjackView(CasinoV2View):
    def __init__(self, bot_instance: CasinoBot, user_id: int, game: dict, dealt: bool = False):
        super().__init__(timeout=3600)
        self.bot = bot_instance
        self.user_id = user_id
        self.game = game
        self.dealt = dealt
        self.rebuild()

    def rebuild(self, image_name="blackjack.png", result_text=None):
        self.clear_items()
        game = self.game
        player_total = blackjack_hand_total(game["player"])
        dealer_total = "?" if "hidden" in game["dealer"] else blackjack_hand_total(game["dealer"])
        title = "## Blackjack" if result_text is None else f"## Blackjack — {result_text}"
        side1 = points_text(game.get("side_21_3", Decimal("0")))
        side2 = points_text(game.get("pairs", Decimal("0")))
        if result_text is None:
            body = (
                f"> **Player Bet:** {points_text(game['bet'])} points · `{money(game['bet'])}`\n"
                f"> **Player Cards:** {' · '.join(blackjack_card_label(c) for c in game['player'])}\n"
                f"> **Dealer Cards:** {' · '.join(blackjack_card_label(c) for c in game['dealer'])}\n"
                f"> **Sidebet¹:** {side1} · **Sidebet²:** {side2}\n"
                f"> **Player Total:** {player_total} · **Dealer Total:** {dealer_total}\n"
                f"> Game ID: `{game['game_id']}`"
            )
        else:
            outcome_line = ("🟢 **YOU WON**" if result_text == "Won" else "🔴 **YOU LOST**" if result_text == "Lost" else "🟡 **PUSH — BET RETURNED**")
            body = (
                f"{outcome_line}\n"
                f"> **Bet Amount:** {points_text(game['bet'])} · `{money(game['bet'])}`\n"
                f"> **Sidebet¹:** {side1} · **Sidebet²:** {side2}\n"
                f"> {game.get('result_summary', f'Player {player_total} vs Dealer {dealer_total}')}"
            )
        avatar_url = game.get("user_avatar_url")
        children = []
        if avatar_url:
            children.append(discord.ui.Section(discord.ui.TextDisplay(title), accessory=discord.ui.Thumbnail(avatar_url)))
        else:
            children.append(discord.ui.TextDisplay(title))
        children.extend([
            discord.ui.TextDisplay(body),
            discord.ui.Separator(visible=True),
            discord.ui.MediaGallery(discord.MediaGalleryItem(media=f"attachment://{image_name}")),
        ])
        if result_text is None and not self.game.get("finished") and self.dealt:
            hit = discord.ui.Button(label="HIT", style=discord.ButtonStyle.primary)
            stand = discord.ui.Button(label="STAND", style=discord.ButtonStyle.success)
            double = discord.ui.Button(label="DOUBLE", style=discord.ButtonStyle.secondary)
            hit.callback = self.hit; stand.callback = self.stand; double.callback = self.double
            buttons = [hit, stand, double]
            if len(game["player"]) == 2 and game["player"][0].split("_of_")[0] == game["player"][1].split("_of_")[0]:
                split = discord.ui.Button(label="SPLIT", style=discord.ButtonStyle.secondary, disabled=True)
                buttons.append(split)
            children.append(discord.ui.ActionRow(*buttons))
        children.append(discord.ui.TextDisplay(f"-# Provably fair · verify with `.verify {game['game_id']}`"))
        if result_text is None:
            accent = GAME_COLOR
        elif result_text == "Won":
            accent = 0x57F287
        elif result_text == "Lost":
            accent = 0xED4245
        else:
            accent = 0xFEE75C
        self.add_item(discord.ui.Container(*children, accent_color=accent))

    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        if interaction.user.id != self.user_id:
            await interaction.response.send_message("This Blackjack game belongs to another player.", ephemeral=True)
            return False
        return True


    async def deal(self, interaction: discord.Interaction):
        self.dealt = True
        file = create_blackjack_image(self.game["player"], self.game["dealer"], bet=self.game["bet"], hidden=True, game_id=self.game.get("game_id"))
        self.rebuild()
        await interaction.response.edit_message(view=self, attachments=[file] if file else [])

    async def hit(self, interaction: discord.Interaction):
        await self.bot.blackjack_hit(interaction, self)

    async def stand(self, interaction: discord.Interaction):
        await self.bot.blackjack_stand(interaction, self)

    async def double(self, interaction: discord.Interaction):
        await self.bot.blackjack_double(interaction, self)


# ============================================================
# BLACKJACK FINISH
# ============================================================
def _card_rank(card: str) -> str:
    return card.split("_of_")[0] if "_of_" in card else card

def _card_suit(card: str) -> str:
    return card.split("_of_")[1] if "_of_" in card else ""

def _card_rank_value(card: str) -> int:
    r = _card_rank(card)
    order = {"jack": 11, "queen": 12, "king": 13, "ace": 14}
    return order.get(r, int(r) if r.isdigit() else 0)

def _is_21_3_win(cards: list[str]):
    if len(cards) != 3 or any(c == "hidden" for c in cards):
        return (False, 0, "Lost")
    ranks = [_card_rank(c) for c in cards]
    suits = [_card_suit(c) for c in cards]
    vals = sorted(_card_rank_value(c) for c in cards)
    flush = len(set(suits)) == 1
    trips = len(set(ranks)) == 1
    straight = vals == [vals[0], vals[0]+1, vals[0]+2] or vals == [2, 3, 14]
    if flush and trips: return (True, 100, "Suited Trips")
    if flush and straight: return (True, 40, "Straight Flush")
    if trips: return (True, 30, "Three of a Kind")
    if straight: return (True, 10, "Straight")
    if flush: return (True, 5, "Flush")
    return (False, 0, "Lost")

def _perfect_pairs_result(cards: list[str]):
    if len(cards) < 2 or any(c == "hidden" for c in cards[:2]):
        return (False, 0, "Lost")
    a, b = cards[0], cards[1]
    if _card_rank(a) != _card_rank(b): return (False, 0, "Lost")
    if _card_suit(a) == _card_suit(b): return (True, 30, "Perfect Pair")
    red = {"diamonds", "hearts"}
    same_color = (_card_suit(a) in red) == (_card_suit(b) in red)
    return (True, 10 if same_color else 5, "Colored Pair" if same_color else "Mixed Pair")



async def _blackjack_finish(
    self,
    interaction: discord.Interaction,
    view: BlackjackView,
    result: str,
):

    game = view.game

    if game["finished"]:
        return

    game["finished"] = True

    player_total = blackjack_hand_total(
        game["player"]
    )

    dealer_total = blackjack_hand_total(
        game["dealer"]
    )

    # ========================================================
    # WIN
    # ========================================================

    if result == "win":

        payout = (
            game["bet"]
            * Decimal("2")
        )

        await self.settle_win(
            game["user_id"],
            game["bet"],
            payout,
            "blackjack",
        )

        title = "Blackjack — Won"
        color = 0x57F287

    # ========================================================
    # PUSH
    # ========================================================

    elif result == "push":

        payout = game["bet"]

        await self.db.change_balance(
            game["user_id"],
            payout,
            kind="blackjack_push",
            note="blackjack",
        )

        fair = self.get_fair_game(game["user_id"])
        await self.db.record_game(
            game["user_id"], game["bet"], Decimal("0"), "blackjack_push",
            result="PUSH",
            game_id=fair.get("game_id") if fair else game.get("game_id"),
            server_hash=fair.get("server_hash") if fair else game.get("server_hash"),
            server_seed=fair.get("server_seed") if fair else game.get("server_seed"),
            client_seed=fair.get("client_seed") if fair else game.get("client_seed"),
            nonce=fair.get("nonce") if fair else game.get("nonce"),
        )
        await self._persist_fair_metadata(game["user_id"], fair)
        self.clear_fair_game(game["user_id"])

        title = "Blackjack — Push"
        color = 0xFEE75C

    # ========================================================
    # LOSS
    # ========================================================

    else:

        payout = Decimal("0")

        await self.settle_loss(
            game["user_id"],
            game["bet"],
            "blackjack",
        )

        title = "Blackjack — Lost"
        color = 0xED4245

    # Settle optional side bets after all cards are visible.
    side_lines = []
    side1 = D(game.get("side_21_3", 0))
    side2 = D(game.get("pairs", 0))
    if side1 > 0:
        win, mult, label = _is_21_3_win([game["player"][0], game["player"][1], game["dealer"][0]])
        if win:
            side_payout = side1 * Decimal(str(mult + 1))
            await self.db.change_balance(game["user_id"], side_payout, kind="blackjack_sidebet", note=f"21+3 {label}")
            side_lines.append(f"Sidebet¹ Won — {label} · +{points_text(side_payout)}")
        else:
            side_lines.append("Sidebet¹ Lost")
    else:
        side_lines.append("Sidebet¹ —")
    if side2 > 0:
        win, mult, label = _perfect_pairs_result(game["player"])
        if win:
            side_payout = side2 * Decimal(str(mult + 1))
            await self.db.change_balance(game["user_id"], side_payout, kind="blackjack_sidebet", note=f"Perfect Pairs {label}")
            side_lines.append(f"Sidebet² Won — {label} · +{points_text(side_payout)}")
        else:
            side_lines.append("Sidebet² Lost")
    else:
        side_lines.append("Sidebet² —")

    if dealer_total > 21:
        comparison = f"Dealer Bust against Player {player_total}"
    elif result == "win":
        comparison = f"Player {player_total} > Dealer {dealer_total}"
    elif result == "push":
        comparison = f"Draw — Player {player_total} = Dealer {dealer_total}"
    else:
        comparison = f"Dealer {dealer_total} > Player {player_total}"
    if result == "win":
        won_text = points_text(payout)
        result_summary = f"{comparison} · Won {won_text}\n" + "\n".join(side_lines)
    elif result == "push":
        result_summary = f"{comparison} · Draw {points_text(payout)}\n" + "\n".join(side_lines)
    else:
        result_summary = f"{comparison} · Lost {points_text(game['bet'])}\n" + "\n".join(side_lines)
    game["result_summary"] = result_summary

    # Remove buttons
    view.clear_items()

    # ========================================================
    # FINAL BLACKJACK IMAGE
    # ========================================================

    file = create_blackjack_image(
        game["player"],
        game["dealer"],
        bet=game["bet"],
        hidden=False,
        result=result,
        game_id=game.get("game_id"),
    )

    # ========================================================
    # FINAL EMBED
    # ========================================================

    result_label = title.split("—")[-1].strip()
    view.rebuild("blackjack.png", result_label)
    await interaction.response.edit_message(
        view=view,
        attachments=[file] if file else [],
    )

    self.active_games.pop(
        game["user_id"],
        None,
    )


CasinoBot.blackjack_finish = _blackjack_finish


# ============================================================
# BLACKJACK HIT
# ============================================================

async def _blackjack_hit(
    self,
    interaction: discord.Interaction,
    view: BlackjackView,
):

    game = view.game

    if game["finished"]:
        return

    game["player"].append(
        game["deck"].pop()
    )

    total = blackjack_hand_total(
        game["player"]
    )

    # Bust
    if total > 21:

        await self.blackjack_finish(
            interaction,
            view,
            "loss",
        )

        return

    # ========================================================
    # UPDATED IMAGE
    # ========================================================

    file = create_blackjack_deal_gif(
        game["player"], game["dealer"], bet=game["bet"], hidden=True,
        game_id=game.get("game_id"),
    )

    view.dealt = True
    view.rebuild("blackjack.gif")
    await interaction.response.edit_message(view=view, attachments=[file] if file else [])
    if interaction.message:
        asyncio.create_task(replace_blackjack_gif_with_still(interaction.message, game, view, delay=3.0))


CasinoBot.blackjack_hit = _blackjack_hit


# ============================================================
# BLACKJACK STAND
# ============================================================

async def _blackjack_stand(
    self,
    interaction: discord.Interaction,
    view: BlackjackView,
):

    game = view.game

    if game["finished"]:
        return

    # Dealer draws until 17+
    while blackjack_hand_total(
        game["dealer"]
    ) < 17:

        game["dealer"].append(
            game["deck"].pop()
        )

    player_total = blackjack_hand_total(
        game["player"]
    )

    dealer_total = blackjack_hand_total(
        game["dealer"]
    )

    # ========================================================
    # DETERMINE RESULT
    # ========================================================

    if dealer_total > 21:

        result = "win"

    elif player_total > dealer_total:

        result = "win"

    elif player_total == dealer_total:

        result = "push"

    else:

        result = "loss"

    await self.blackjack_finish(
        interaction,
        view,
        result,
    )


CasinoBot.blackjack_stand = _blackjack_stand


# ============================================================
# BLACKJACK DOUBLE
# ============================================================

async def _blackjack_double(
    self,
    interaction: discord.Interaction,
    view: BlackjackView,
):

    game = view.game

    if game["finished"]:
        return

    # Double only on first two cards
    if len(game["player"]) != 2:

        await interaction.response.send_message(
            embed=base_embed(
                title="Blackjack",
                description=(
                    "Double is only available "
                    "on your first two cards."
                ),
                color=0xED4245,
            ),
        )

        return

    extra_bet = game["bet"]

    success = await self.deduct_bet(
        game["user_id"],
        extra_bet,
        "blackjack-double",
    )

    if not success:

        await interaction.response.send_message(
            embed=base_embed(
                title="Blackjack",
                description="You Dont Have Enough Crypto",
                color=0xED4245,
            ),
        )

        return

    # Double the wager
    game["bet"] += extra_bet

    # Draw exactly one card
    game["player"].append(
        game["deck"].pop()
    )

    # Bust
    if blackjack_hand_total(
        game["player"]
    ) > 21:

        await self.blackjack_finish(
            interaction,
            view,
            "loss",
        )

        return

    # Automatically stand
    await self.blackjack_stand(
        interaction,
        view,
    )


CasinoBot.blackjack_double = _blackjack_double


