@prefix_command(name="blackjack", aliases=["bj"])
async def blackjack(
    interaction: discord.Interaction,
    amount: str,
    side_21_3: Optional[str] = None,
    pairs: Optional[str] = None,
):

    balance = await bot.get_balance(interaction.user.id)
    value = usd_from_points_input(amount, balance)
    side1 = usd_from_points_input(side_21_3, balance) if side_21_3 else Decimal("0")
    side2 = usd_from_points_input(pairs, balance) if pairs else Decimal("0")
    if side1 is None or side2 is None:
        await interaction.response.send_message(embed=error_embed("Blackjack", "Side bets must be entered in points.")); return
    total_required = value + side1 + side2 if value is not None else Decimal("0")

    # ========================================================
    # MINIMUM BET
    # ========================================================

    if value is None or value < MIN_BET:

        await interaction.response.send_message(
            embed=base_embed(
                title="Blackjack",
                description=(
                    "Minimum Blackjack bet is **10** (`$0.10`)."
                ),
                color=0xED4245,
            ),
        )

        return

    # ========================================================
    # TAKE BET
    # ========================================================

    if total_required > balance:
        await interaction.response.send_message(embed=error_embed("Blackjack", f"You need **{points_text(total_required)}** total for the bet + side bets.")); return

    success = await bot.deduct_bet(
        interaction.user.id,
        total_required,
        "blackjack",
    )

    if not success:

        await interaction.response.send_message(
            embed=base_embed(
                title="Blackjack",
                description="You Dont Have Enough Crypto",
                color=0xED4245,
            ),
        )

        return

    # Side bets are real wagers too: count them toward rank progress and
    # unlock any bonus wagering requirement when they are played.
    side_wager = side1 + side2
    if side_wager > 0:
        await bot.db.pool.execute("UPDATE users SET wagered=wagered+$2, bonus_wager_remaining=GREATEST(0, bonus_wager_remaining-$2) WHERE user_id=$1", interaction.user.id, side_wager)

    # ========================================================
    # DECK / PROVABLY FAIR DATA
    # ========================================================

    server_seed = bot.create_server_seed()
    client_seed = bot.create_client_seed(interaction.user.id)
    game_id = bot.next_game_id()
    deck = blackjack_deck(server_seed, client_seed, 0, bot)

    player = [
        deck.pop(),
        deck.pop(),
    ]

    dealer = [
        deck.pop(),
        "hidden",
    ]

    # ========================================================
    # GAME STATE
    # ========================================================

    game = {
        "user_id": interaction.user.id,

        "bet": value,

        "deck": deck,

        "player": player,

        "dealer": dealer,

        "game_id": game_id,

        "server_seed": server_seed,

        "server_hash": bot.server_hash(server_seed),

        "client_seed": client_seed,

        "nonce": 0,

        "finished": False,

        "guild_icon_url": None,
        "user_avatar_url": str(interaction.user.display_avatar.url),

        "side_21_3": (
            side1
        ),

        "pairs": (
            side2
        ),
    }

    bot.register_fair_game(
        interaction.user.id, "blackjack", game_id, server_seed, client_seed, 0,
        "Game-state dependent",
        "52-card deterministic fair shuffle; player/dealer decisions affect the final win chance.",
    )

    bot.active_games[
        interaction.user.id
    ] = game

    # ========================================================
    # COMPONENTS V2 DEAL SCREEN
    # ========================================================

    view = BlackjackView(bot, interaction.user.id, game, dealt=False)
    initial_file = create_blackjack_deal_gif(game["player"], game["dealer"], bet=game["bet"], hidden=True, game_id=game.get("game_id"))
    view.rebuild("blackjack.gif")
    await interaction.response.send_message(view=view, file=initial_file)
    # Initial four-card deal GIF stays visible for 7 seconds before the still image.
    await asyncio.sleep(7.0)
    if not game.get("finished"):
        view.dealt = True
        still = create_blackjack_image(game["player"], game["dealer"], bet=game["bet"], hidden=True, game_id=game.get("game_id"))
        view.rebuild("blackjack.png")
        await interaction.edit_original_response(view=view, attachments=[still] if still else [])


