async def get_house_balances():
    row = await bot.db.pool.fetchrow(
        "SELECT balance, ltc_balance, sol_balance FROM house WHERE id=1"
    )
    if not row:
        return {
            "total": Decimal("0"),
            "LTC": Decimal("0"),
            "LTC_USD": Decimal("0"),
            "SOL": Decimal("0"),
            "SOL_USD": Decimal("0"),
        }

    ltc_qty = D(row["ltc_balance"])
    sol_qty = D(row["sol_balance"])

    ltc_price = await get_crypto_usd_price("LTC")
    sol_price = await get_crypto_usd_price("SOL")

    ltc_usd = (ltc_qty * ltc_price) if ltc_price and ltc_price > 0 else Decimal("0")
    sol_usd = (sol_qty * sol_price) if sol_price and sol_price > 0 else Decimal("0")

    # House Balance is only the LTC + SOL reserve. USDT is intentionally
    # not included or displayed in the house-balance panel.
    total = ltc_usd + sol_usd

    return {
        "total": total,
        "LTC": ltc_qty,
        "LTC_USD": ltc_usd,
        "SOL": sol_qty,
        "SOL_USD": sol_usd,
    }


