async def fetch_public_ltc_balance(address: str) -> Decimal:
    """Fetch confirmed public Litecoin address balance from BlockCypher (Litoshis)."""
    url = f"https://api.blockcypher.com/v1/ltc/main/addrs/{address}/balance"
    async with bot.http_session.get(url, timeout=aiohttp.ClientTimeout(total=12)) as resp:
        resp.raise_for_status()
        payload = await resp.json()
    return Decimal(str(payload.get("balance", 0))) / Decimal("100000000")


