async def create_rank_image(user: discord.User | discord.Member, wagered_usd: Decimal) -> discord.File:
    WIDTH, HEIGHT = 1536, 728
    BG = (8, 16, 24, 255)
    PANEL = (17, 30, 41, 255)
    BORDER = (42, 61, 76, 255)
    WHITE = (245, 247, 250, 255)
    MUTED = (164, 174, 184, 255)
    current = rank_for_wager(wagered_usd)
    nxt = next_rank_for_wager(wagered_usd)
    wagered_pts = points_from_usd(wagered_usd)
    if nxt:
        next_pts = points_from_usd(nxt["wager"])
        previous_pts = points_from_usd(current["wager"])
        progress_total = max(Decimal("1"), next_pts - previous_pts)
        progress_value = max(Decimal("0"), min(progress_total, wagered_pts - previous_pts))
        progress = float(progress_value / progress_total)
        remaining_pts = max(Decimal("0"), next_pts - wagered_pts)
        next_text = nxt["name"]
    else:
        progress = 1.0
        remaining_pts = Decimal("0")
        next_text = "MAX RANK"

    def font(size, bold=False):
        paths = [
            '/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf' if bold else '/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf',
            '/usr/share/fonts/truetype/liberation2/LiberationSans-Bold.ttf' if bold else '/usr/share/fonts/truetype/liberation2/LiberationSans-Regular.ttf',
        ]
        for path in paths:
            try: return ImageFont.truetype(path, size)
            except Exception: pass
        return ImageFont.load_default()

    image = Image.new('RGBA', (WIDTH, HEIGHT), BG)
    draw = ImageDraw.Draw(image)
    draw.rounded_rectangle((66, 68, WIDTH-66, HEIGHT-68), radius=40, fill=PANEL, outline=BORDER, width=4)
    avatar_size = 220
    avatar_x, avatar_y = 120, 154
    avatar = None
    try:
        async with bot.http_session.get(str(user.display_avatar.with_size(256).url)) as response:
            if response.status == 200:
                avatar = Image.open(io.BytesIO(await response.read())).convert('RGBA').resize((avatar_size, avatar_size), Image.Resampling.LANCZOS)
    except Exception:
        pass
    mask = Image.new('L', (avatar_size, avatar_size), 0)
    ImageDraw.Draw(mask).ellipse((0, 0, avatar_size, avatar_size), fill=255)
    if avatar is not None:
        avatar.putalpha(mask)
        image.alpha_composite(avatar, (avatar_x, avatar_y))
    else:
        draw.ellipse((avatar_x, avatar_y, avatar_x+avatar_size, avatar_y+avatar_size), fill=current["color"], outline=(255,255,255,50), width=3)
        initials = ''.join(part[0] for part in str(user.display_name).split()[:2]).upper() or 'P'
        box = draw.textbbox((0,0), initials, font=font(82, True))
        draw.text((avatar_x+(avatar_size-(box[2]-box[0]))/2, avatar_y+(avatar_size-(box[3]-box[1]))/2-8), initials, font=font(82, True), fill=(18,23,29,255))
    draw.text((390, 145), str(user.display_name), font=font(62, True), fill=WHITE)
    draw.text((390, 235), current["name"], font=font(60, True), fill=current["color"])
    draw.text((390, 325), f'{points_text(wagered_usd)} wagered', font=font(32), fill=MUTED)
    bar_x1, bar_y1, bar_x2, bar_y2 = 125, 490, WIDTH-125, 538
    draw.rounded_rectangle((bar_x1, bar_y1, bar_x2, bar_y2), radius=24, fill=(39,53,66,255))
    fill_w = int((bar_x2-bar_x1) * progress)
    if fill_w > 0:
        draw.rounded_rectangle((bar_x1, bar_y1, bar_x1+max(20, fill_w), bar_y2), radius=24, fill=current["color"])
    percent = f'{progress*100:.1f}%'
    box = draw.textbbox((0,0), percent, font=font(28, True))
    draw.text(((WIDTH-(box[2]-box[0]))/2, 495), percent, font=font(28, True), fill=WHITE)
    remaining_label = f'{remaining_pts:,.2f}' if remaining_pts != remaining_pts.to_integral_value() else f'{int(remaining_pts):,}'
    draw.text((125, 585), f'{remaining_label} to {next_text}', font=font(30), fill=MUTED)
    reward = nxt.get('reward', Decimal('0')) if nxt else Decimal('0')
    right = f'Next reward: {int(reward)}' if nxt else 'Next reward: MAX'
    box = draw.textbbox((0,0), right, font=font(30))
    draw.text((WIDTH-125-(box[2]-box[0]), 585), right, font=font(30), fill=MUTED)
    out = io.BytesIO(); image.save(out, format='PNG', optimize=True); out.seek(0)
    return discord.File(out, filename='rank.png')

@prefix_command(name="rank")
async def rank_command_final(interaction: PrefixInteraction):
    row = await bot.get_db_user(interaction.user.id)
    wagered = D(row.get('wagered', 0)) if row else Decimal('0')
    current, nxt = rank_progress(wagered)
    file = await create_rank_image(interaction.user, wagered)
    if nxt:
        remaining = points_from_usd(nxt['wager'] - wagered)
        next_line = nxt['name']
        wager_line = f'{remaining:,.2f}' if remaining != remaining.to_integral_value() else f'{int(remaining):,}'
    else:
        next_line = 'MAX RANK'; wager_line = '0'
    view = CasinoV2View(timeout=300)
    view.add_item(discord.ui.Container(
        discord.ui.TextDisplay('## Rank Progress'),
        discord.ui.MediaGallery(discord.MediaGalleryItem(media='attachment://rank.png')),
        discord.ui.TextDisplay(f'> **Current Rank:** {current["name"]}\n> **Next Rank:** {next_line}\n> **Wager {wager_line} to reach Next rank**\n> **Total Wagered:** {points_text(wagered)} · `{money(wagered)}`'),
        accent_color=current['color'],
    ))
    await interaction.response.send_message(view=view, file=file)

DAILY_REQUIREMENT_NORMALIZED = "ggarticbestcasino"


def _normalise_daily_requirement(text: str) -> str:
    """Ignore capitalization, spaces, and punctuation when matching a status."""
    return re.sub(r"[^a-z0-9]", "", str(text).casefold())


def _member_has_daily_status(member) -> bool:
    target = DAILY_REQUIREMENT_NORMALIZED
    for activity in getattr(member, "activities", ()) or ():
        # Discord custom status text is generally exposed as CustomActivity.name/state.
        values = [getattr(activity, "name", ""), getattr(activity, "state", "")]
        combined = _normalise_daily_requirement(" ".join(str(v or "") for v in values))
        if target in combined:
            return True
    return False


def _find_member_with_daily_status(user_id: int):
    for guild in bot.guilds:
        member = guild.get_member(user_id)
        if member and _member_has_daily_status(member):
            return member
    return None


@prefix_command(name="daily")
async def daily_command_final(interaction: PrefixInteraction):
    user_id = interaction.user.id
    if bot.db is None or getattr(bot.db, "pool", None) is None:
        await interaction.response.send_message(embed=error_embed('Daily Reward', 'The database is still starting. Please try again shortly.')); return
    member = _find_member_with_daily_status(user_id)
    if not member:
        embed = base_embed(
            'Daily Requirement',
            'Your Discord **custom status** must contain:\n'
            '` .gg/artic Best Casino `\n\n'
            'Capitalization, spaces, and punctuation differences are ignored. Set your status, then try `.daily` again.',
            0xFEE75C,
        )
        await interaction.response.send_message(embed=embed); return
    async with bot.db.pool.acquire() as conn:
        await conn.execute('INSERT INTO users(user_id) VALUES($1) ON CONFLICT(user_id) DO NOTHING', user_id)
        claimed = await conn.fetchrow("""
            UPDATE users
            SET daily_claim_at=NOW(), updated_at=NOW()
            WHERE user_id=$1
              AND (daily_claim_at IS NULL OR daily_claim_at <= NOW() - INTERVAL '24 hours')
            RETURNING user_id
        """, user_id)
    if not claimed:
        remaining = await bot.db.pool.fetchval("SELECT GREATEST(0, EXTRACT(EPOCH FROM ((daily_claim_at + INTERVAL '24 hours') - NOW()))) FROM users WHERE user_id=$1", user_id)
        hours = int((float(remaining or 0) + 3599) // 3600)
        embed = base_embed('Daily Reward', f'> <:blast:1557392029766525018> You already claimed your daily reward.\n> Come back in **{hours}h**.', 0xFEE75C)
        await interaction.response.send_message(embed=embed); return
    reward_usd = Decimal('0.02')
    ok = await bot.db.change_balance(user_id, reward_usd, kind='daily', note='Daily reward: 2 points')
    if not ok:
        await interaction.response.send_message(embed=error_embed('Daily Reward', 'The daily reward could not be credited.')); return
    balance = await bot.get_balance(user_id)
    embed = base_embed('Daily Reward', f'<:PL_Money:1557396540287623199> **+2** added to your balance.\n<:Wallet:1557396484201123912> **New balance:** **{points_text(balance)}** · `{money(balance)}`\n\nCome back in 24h for more!\n\n-# Daily credit requires 2× wagering before withdrawal.', 0x57F287)
    await interaction.response.send_message(embed=embed)




# ============================================================
# HILO — HIGHER / LOWER (PREFIX GAME)
# ============================================================
def create_hilo_image(previous_card: Optional[str], current_card: str, *, bet, multiplier=Decimal('1.0'), choice=None, outcome=None, game_id=None) -> Optional[discord.File]:
    """Render a readable Artic green felt Hilo table using the repository card PNGs."""
    try:
        W, H = 1536, 900
        im = Image.new('RGB', (W, H), (255, 255, 255))
        d = ImageDraw.Draw(im)
        def f(size, bold=False):
            candidates = [
                '/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf' if bold else '/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf',
                '/usr/share/fonts/truetype/liberation2/LiberationSans-Bold.ttf' if bold else '/usr/share/fonts/truetype/liberation2/LiberationSans-Regular.ttf'
            ]
            for fp in candidates:
                try: return ImageFont.truetype(fp, size)
                except Exception: pass
            return ImageFont.load_default()
        green=(39, 235, 132); pale=(229, 242, 234); muted=(135, 174, 151)
        d.rounded_rectangle((18,18,W-18,H-18), radius=38, outline=(30,142,83), width=5)
        d.text((72,52), 'Artic  /  HILO', font=f(38,True), fill=green)
        d.text((74,112), 'HIGHER OR LOWER', font=f(23), fill=muted)
        d.rounded_rectangle((72,180,W-72,770), radius=32, fill=(5,32,20), outline=(17,76,47), width=3)
        def load_card(name):
            if not name or name == 'hidden': return None
            path=card_path(name)
            if not path.exists(): return None
            try:
                card=Image.open(path).convert('RGBA')
                maxw,maxh=290,430
                ratio=min(maxw/card.width,maxh/card.height)
                return card.resize((int(card.width*ratio),int(card.height*ratio)),Image.Resampling.LANCZOS)
            except Exception: return None
        def draw_card(name, x, y):
            card=load_card(name)
            if card:
                im.paste(card,(x,y),card if card.mode=='RGBA' else None)
            else:
                d.rounded_rectangle((x,y,x+290,y+430),radius=20,fill=(9,64,38),outline=green,width=5)
                d.text((x+45,y+165),'CARD',font=f(48,True),fill=pale)
        if previous_card:
            # Current card stays on the left; the newly drawn card is on the right.
            draw_card(previous_card, 265, 250)
            draw_card(current_card, 980, 250)
            symbol = '>' if _card_rank_value(current_card) > _card_rank_value(previous_card) else '<' if _card_rank_value(current_card) < _card_rank_value(previous_card) else '='
            d.text((720,415), symbol, font=f(100,True), fill=green if outcome=='win' else (244,82,98) if outcome=='loss' else pale, anchor='mm')
            d.text((410,700),'CURRENT CARD',font=f(22,True),fill=muted,anchor='mm')
            d.text((1125,700),'NEXT CARD',font=f(22,True),fill=muted,anchor='mm')
        else:
            draw_card(current_card, (W-290)//2, 230)
            d.text((W//2,700),'STARTING CARD',font=f(24,True),fill=muted,anchor='mm')
        d.rounded_rectangle((72,790,W-72,855),radius=18,fill=(7,42,25),outline=(24,116,68),width=2)
        d.text((100,805),f'BET  {points_text(D(bet))} PTS',font=f(25,True),fill=pale)
        d.text((W//2,805),f'MULTI  {float(multiplier):.2f}x',font=f(25,True),fill=green)
        if game_id is not None: d.text((W-360,812),f'GAME #{game_id}',font=f(20),fill=muted)
        if outcome == 'win':
            d.rounded_rectangle((420,135,1116,205),radius=20,fill=(6,93,49),outline=green,width=2)
            d.text((768,170),'CORRECT  •  KEEP GOING OR CASH OUT',font=f(23,True),fill=pale,anchor='mm')
        elif outcome == 'loss':
            d.rounded_rectangle((420,135,1116,205),radius=20,fill=(103,21,33),outline=(244,82,98),width=2)
            d.text((768,170),'WRONG GUESS  •  BET LOST',font=f(23,True),fill=pale,anchor='mm')
        elif outcome == 'cashout':
            d.rounded_rectangle((420,135,1116,205),radius=20,fill=(6,93,49),outline=green,width=2)
            d.text((768,170),'CASHED OUT',font=f(23,True),fill=pale,anchor='mm')
        out=io.BytesIO(); im.save(out,format='PNG',optimize=True); out.seek(0)
        return discord.File(out,filename='hilo.png')
    except Exception as exc:
        print(f'[HILO IMAGE] {type(exc).__name__}: {exc}')
        return None


def hilo_choice_odds(game, direction: str):
    """Return (chance, next-guess multiplier, cumulative multiplier) from remaining deck."""
    current_value = _card_rank_value(game['current'])
    deck = game.get('deck') or []
    total = len(deck)
    if total <= 0:
        return Decimal('0'), Decimal('0'), Decimal('0')
    favorable = sum(1 for card in deck if (_card_rank_value(card) > current_value if direction == 'higher' else _card_rank_value(card) < current_value))
    chance = Decimal(favorable) / Decimal(total) if favorable else Decimal('0')
    if chance <= 0:
        return chance, Decimal('0'), Decimal('0')
    # 96% theoretical return: lower chance means a larger multiplier.
    step_multi = (Decimal('0.96') / chance).quantize(Decimal('0.01'), rounding=ROUND_DOWN)
    cumulative = (D(game.get('multiplier', 1)) * step_multi).quantize(Decimal('0.01'), rounding=ROUND_DOWN)
    return chance, step_multi, cumulative


class HiloView(CasinoV2View):
    def __init__(self, bot_instance, game):
        super().__init__(timeout=900)
        self.bot=bot_instance
        self.game=game
        self.rebuild()

    def rebuild(self, image_name='hilo.png'):
        self.clear_items()
        g=self.game
        finished=g.get('finished',False)
        if finished:
            status='WON' if g.get('outcome') in {'win','cashout'} else 'LOST'
            color=0x35D07F if status=='WON' else 0xED4245
            multi='0x' if status=='LOST' else f"{g['multiplier']:.2f}x"
            profit=(D(g.get('payout',0))-D(g['bet'])) if status=='WON' else -D(g['bet'])
            body=(f"**Bet:** {points_text(g['bet'])}\n"
                  f"**Current Card:** {blackjack_card_label(g['current'])}\n"
                  f"**Multi:** {multi}\n"
                  f"**Profit:** {'+' if profit>0 else ''}{points_text(profit)}\n"
                  f"**Result:** {'YOU WON' if status=='WON' else 'YOU LOST'}")
        else:
            color=0x35D07F
            _, _, high_total = hilo_choice_odds(g, 'higher')
            _, _, low_total = hilo_choice_odds(g, 'lower')
            body=(f"**Bet:** {points_text(g['bet'])}\n"
                  f"**Current Card:** {blackjack_card_label(g['current'])}\n"
                  f"**Multi:** {g['multiplier']:.2f}x\n"
                  f"**Chances for next card:** Higher {hilo_choice_odds(g, 'higher')[0]*100:.1f}% · Lower {hilo_choice_odds(g, 'lower')[0]*100:.1f}%\n"
                  f"Higher risk = higher multiplier. Choose a direction to continue.")
        children=[]
        title='## Hilo • Artic'
        avatar=g.get('avatar_url')
        children.append(discord.ui.Section(discord.ui.TextDisplay(title),accessory=discord.ui.Thumbnail(avatar)) if avatar else discord.ui.TextDisplay(title))
        children.extend([discord.ui.TextDisplay(body),discord.ui.Separator(visible=True),discord.ui.MediaGallery(discord.MediaGalleryItem(media=f'attachment://{image_name}'))])
        if not finished:
            _, _, high_total = hilo_choice_odds(g, 'higher')
            _, _, low_total = hilo_choice_odds(g, 'lower')
            high_label = f"HIGH ({high_total:.2f}x)" if high_total > 0 else "HIGH (—)"
            low_label = f"LOW ({low_total:.2f}x)" if low_total > 0 else "LOW (—)"
            high=discord.ui.Button(label=high_label,style=discord.ButtonStyle.success,emoji='⬆️',disabled=high_total <= 0)
            low=discord.ui.Button(label=low_label,style=discord.ButtonStyle.primary,emoji='⬇️',disabled=low_total <= 0)
            high.callback=self.higher; low.callback=self.lower
            children.append(discord.ui.ActionRow(high,low))
            if g.get('can_cashout'):
                cash=discord.ui.Button(label='CASH OUT',style=discord.ButtonStyle.success,emoji='<:money_bag:1557393182956847226>')
                cash.callback=self.cashout
                children.append(discord.ui.ActionRow(cash))
        children.append(discord.ui.TextDisplay(f"-# Provably fair · verify with `.verify {g['game_id']}`"))
        self.add_item(discord.ui.Container(*children,accent_color=color))

    async def interaction_check(self, interaction):
        if interaction.user.id != self.game['user_id']:
            await interaction.response.send_message('This Hilo game belongs to another player.',ephemeral=True)
            return False
        if self.game.get('finished'):
            await interaction.response.send_message('This Hilo game has ended.',ephemeral=True)
            return False
        return True

    async def _guess(self, interaction, direction):
        g=self.game
        if not await self.interaction_check(interaction): return
        previous=g['current']
        _, step_multi, _ = hilo_choice_odds(g, direction)
        if not g['deck']:
            g['deck']=blackjack_deck(g['server_seed'],g['client_seed'],g['nonce']+1,self.bot)
            g['nonce']+=1
        next_card=g['deck'].pop()
        prev_value=_card_rank_value(previous); next_value=_card_rank_value(next_card)
        correct=(next_value>prev_value) if direction=='higher' else (next_value<prev_value)
        g['previous']=previous; g['current']=next_card; g['last_direction']=direction
        if correct:
            g['multiplier']=(g['multiplier']*step_multi).quantize(Decimal('0.01'), rounding=ROUND_DOWN)
            g['can_cashout']=True
            g['outcome']='win'
            self.bot.register_fair_game(g['user_id'],'hilo',g['game_id'],g['server_seed'],g['client_seed'],g['nonce'], 'Higher/Lower; dynamic risk multiplier based on remaining-card odds', f"Direction: {direction}; {previous} -> {next_card}; Correct")
            file=create_hilo_image(previous,next_card,bet=g['bet'],multiplier=g['multiplier'],choice=direction,outcome='win',game_id=g['game_id'])
            self.rebuild()
            await interaction.response.edit_message(view=self,attachments=[file] if file else [])
            return
        g['finished']=True; g['outcome']='loss'; g['multiplier']=Decimal('0'); g['payout']=Decimal('0')
        self.bot.register_fair_game(g['user_id'],'hilo',g['game_id'],g['server_seed'],g['client_seed'],g['nonce'], 'Higher/Lower; dynamic risk multiplier based on remaining-card odds', f"Direction: {direction}; {previous} -> {next_card}; Incorrect")
        await self.bot.settle_loss(g['user_id'],g['bet'],'hilo',result='LOSS')
        file=create_hilo_image(previous,next_card,bet=g['bet'],multiplier=Decimal('0'),choice=direction,outcome='loss',game_id=g['game_id'])
        self.rebuild()
        await interaction.response.edit_message(view=self,attachments=[file] if file else [])
        self.bot.active_games.pop(g['user_id'],None)

    async def higher(self, interaction): await self._guess(interaction,'higher')
    async def lower(self, interaction): await self._guess(interaction,'lower')

    async def cashout(self, interaction):
        if not await self.interaction_check(interaction): return
        g=self.game
        payout=(g['bet']*g['multiplier']).quantize(Decimal('0.0001'))
        g['finished']=True; g['outcome']='cashout'; g['payout']=payout
        self.bot.register_fair_game(g['user_id'],'hilo',g['game_id'],g['server_seed'],g['client_seed'],g['nonce'],'Higher/Lower; dynamic risk multiplier based on remaining-card odds',f"Cashout at {g['multiplier']:.2f}x")
        await self.bot.settle_win(g['user_id'],g['bet'],payout,'hilo',result='WIN')
        file=create_hilo_image(g.get('previous'),g['current'],bet=g['bet'],multiplier=g['multiplier'],outcome='cashout',game_id=g['game_id'])
        self.rebuild()
        await interaction.response.edit_message(view=self,attachments=[file] if file else [])
        self.bot.active_games.pop(g['user_id'],None)


@prefix_command(name='hilo')
async def hilo_command(interaction: PrefixInteraction, amount: str):
    """Play Higher or Lower: .hilo <amount> (points)."""
    user_id=interaction.user.id
    balance=await bot.get_balance(user_id)
    bet=usd_from_points_input(amount,balance)
    if bet is None or bet < Decimal('0.10'):
        await interaction.response.send_message(embed=error_embed('Hilo • Artic','Minimum bet is **$0.05**. Usage: `.hilo 0.05`')); return
    if user_id in getattr(bot,'active_games',{}):
        await interaction.response.send_message(embed=error_embed('Hilo • Artic','Finish your active game before starting another.')); return
    if bet>balance:
        await interaction.response.send_message(embed=error_embed('Hilo • Artic',f'Insufficient balance. Your balance is {points_text(balance)} points.')); return
    if not await bot.deduct_bet(user_id,bet,'hilo'):
        await interaction.response.send_message(embed=error_embed('Hilo • Artic','Could not place the bet; check your balance.')); return
    server_seed=bot.create_server_seed(); client_seed=bot.create_client_seed(user_id); game_id=bot.next_game_id()
    deck=blackjack_deck(server_seed,client_seed,0,bot)
    first=deck.pop()
    game={'user_id':user_id,'bet':bet,'deck':deck,'current':first,'previous':None,'multiplier':Decimal('1.00'),'can_cashout':False,'finished':False,'outcome':None,'payout':Decimal('0'),'game_id':game_id,'server_seed':server_seed,'client_seed':client_seed,'nonce':0,'avatar_url':str(interaction.user.display_avatar.url)}
    bot.register_fair_game(user_id,'hilo',game_id,server_seed,client_seed,0,'Higher/Lower; dynamic risk multiplier based on remaining-card odds',f'Starting card: {first}')
    bot.active_games[user_id]={'game':'hilo','game_id':game_id}
    file=create_hilo_image(None,first,bet=bet,multiplier=game['multiplier'],game_id=game_id)
    view=HiloView(bot,game)
    await interaction.response.send_message(view=view,file=file) if file else await interaction.response.send_message(view=view)




