@prefix_command(name="stats")
async def stats_command_final(interaction: PrefixInteraction, stat: str = "", user: str = "", value: str = ""):
    # Owner correction syntax: .stats deposit @user 100 (amount is points).
    if stat:
        try: owner_id = int(getattr(config, "OWNER_ID", BOT_OWNER_ID))
        except (TypeError, ValueError): owner_id = BOT_OWNER_ID
        if interaction.user.id != owner_id:
            await interaction.response.send_message(embed=error_embed("Permission Denied", "Only the bot owner can edit player stats.")); return
        user_id = _target_user_id(user)
        amount = usd_from_points_admin(value)
        stat_key = stat.lower().strip()
        columns = {"deposit":"lifetime_deposit", "deposited":"lifetime_deposit", "withdraw":"lifetime_withdraw", "withdrawn":"lifetime_withdraw", "wager":"wagered", "wagered":"wagered", "balance":"balance"}
        if user_id is None or amount is None or stat_key not in columns:
            await interaction.response.send_message(embed=error_embed("Invalid Arguments", "Correct usage: `.stats deposit @user 100`\nStats: `deposit`, `withdraw`, `wager`, `balance`. Amount is in points.")); return
        await bot.db.user(user_id)
        col = columns[stat_key]
        await bot.db.pool.execute(f"UPDATE users SET {col}=$2, updated_at=NOW() WHERE user_id=$1", user_id, amount)
        await interaction.response.send_message(embed=success_embed("Stats Updated", f"Updated **{stat_key}** for <@{user_id}> to **{points_text(amount)}** (~**{money(amount)}**).")); return
    row = await bot.get_db_user(interaction.user.id)
    if not row:
        await interaction.response.send_message("Account not found.")
        return
    wagered=D(row.get("wagered",0)); balance=D(row.get("balance",0))
    tips_sent=int(row.get("tips_sent",0) or 0); tips_received=int(row.get("tips_received",0) or 0)
    rank = rank_for_wager(wagered)
    try:
        last7 = D(await bot.db.pool.fetchval("SELECT COALESCE(SUM(bet),0) FROM game_history WHERE user_id=$1 AND created_at >= NOW() - INTERVAL '7 days'", interaction.user.id) or 0)
    except Exception:
        last7 = Decimal('0')
    created=interaction.user.created_at
    now=datetime.now(timezone.utc)
    age_days=max(0,(now-created).days) if created else 0
    age_text=f"{age_days} days" if age_days < 365 else f"{age_days//365}y {(age_days%365)//30}mo"
    embed=base_embed(f"{interaction.user.display_name}'s Stats", "", 0xFEE75C)
    embed.add_field(name="<:Wallet:1557396484201123912> Balance", value=f"**{points_text(balance)}** · `{money(balance)}`", inline=False)
    embed.add_field(name="Wagered", value=f"**{points_text(wagered)}** · `{money(wagered)}`", inline=True)
    embed.add_field(name="Rank", value=f"**{rank['name']}**", inline=True)
    embed.add_field(name="Tips given", value=f"**{tips_sent:,}**", inline=True)
    embed.add_field(name="Tips received", value=f"**{tips_received:,}**", inline=True)
    embed.add_field(name="Acc age", value=f"**{age_text}**", inline=True)
    embed.add_field(name="Last 7 Day Wagered", value=f"**{points_text(last7)}** · `{money(last7)}`", inline=False)
    try: embed.set_thumbnail(url=str(interaction.user.display_avatar.url))
    except Exception: pass
    await interaction.response.send_message(embed=embed)

@prefix_command(name="history")
async def history_command_final(interaction: PrefixInteraction):
    rows=await bot.db.pool.fetch("SELECT game,bet,result,created_at,choice,fair_details,payout,game_id FROM game_history WHERE user_id=$1 ORDER BY created_at DESC LIMIT 10", interaction.user.id)
    lines=[f"## <:Wallet:1557396484201123912> Bet History - {interaction.user.display_name}"]
    if not rows: lines.append("> No games played yet.")
    for row in rows:
        result=str(row['result'] or '').upper()
        icon='✓' if result in {'WIN','WON','BLACKJACK'} or D(row['payout'])>D(row['bet']) else '✕'
        game=str(row['game']).replace('_',' ').title()
        choice=str(row['choice'] or '')
        if not choice:
            details=str(row['fair_details'] or '')
            m=re.search(r'Selected side:\s*([^\n]+)', details, re.I)
            choice=m.group(1).strip() if m else ('—' if game.lower() not in {'mines'} else 'mines')
        outcome='won' if icon=='✓' else ('push' if result=='PUSH' else 'lose')
        lines.append(f"> {icon} **{game}** · **{money(row['bet'])}** · `{choice}` · **{outcome}**")
    view=CasinoV2View(timeout=180)
    view.add_item(discord.ui.Container(discord.ui.TextDisplay("\n".join(lines)),accent_color=0x57F287))
    await interaction.response.send_message(view=view)

class LeaderboardView(CasinoV2View):
    PERIODS = {"Daily": "1 day", "Weekly": "7 days", "Monthly": "30 days"}

    def __init__(self, rows, period="Weekly", owner_id=None):
        super().__init__(timeout=300)
        self.rows = rows
        self.period = period
        self._owner_id = owner_id
        self.rebuild()

    def rebuild(self):
        self.clear_items()
        lines = [f"## <:PL_Money:1557396540287623199> Artic {self.period} Leaderboard",
                 f"> Top 10 players by wagered points in the last {self.PERIODS[self.period].replace(' day',' day').replace(' days',' days')}.", ""]
        if not self.rows:
            lines.append("> No wagers recorded for this period yet.")
        for i, row in enumerate(self.rows[:10], 1):
            uid = int(row['user_id'])
            member = bot.get_user(uid)
            name = member.display_name if member else f"User {uid}"
            lines.append(f"**{i}.** {name} — **{points_text(D(row['wagered']))}** (`{money(D(row['wagered']))}`)")
        buttons=[]
        for period in self.PERIODS:
            button=discord.ui.Button(label=period, style=discord.ButtonStyle.success if period == self.period else discord.ButtonStyle.secondary)
            async def callback(interaction, selected=period):
                if self._owner_id is not None and interaction.user.id != self._owner_id:
                    return await interaction.response.send_message("This leaderboard belongs to another user.", ephemeral=True)
                try:
                    rows = await fetch_leaderboard_rows(selected)
                    self.rows, self.period = rows, selected
                    self.rebuild()
                    await interaction.response.edit_message(view=self)
                except Exception as exc:
                    print(f"[LB] Refresh error: {type(exc).__name__}: {exc}")
                    await interaction.response.send_message("Could not refresh this leaderboard right now.", ephemeral=True)
            button.callback=callback
            buttons.append(button)
        self.add_item(discord.ui.Container(discord.ui.TextDisplay("\n".join(lines)), discord.ui.ActionRow(*buttons), accent_color=0x35D07F))

async def fetch_leaderboard_rows(period="Weekly"):
    """Fetch period wager totals, with a safe lifetime fallback for older schemas."""
    if bot.db is None or getattr(bot.db, "pool", None) is None:
        raise RuntimeError("Database pool is not ready")
    interval = {"Daily": "1 day", "Weekly": "7 days", "Monthly": "30 days"}.get(period, "7 days")
    try:
        rows = await bot.db.pool.fetch(
            "SELECT user_id, COALESCE(SUM(bet),0) AS wagered "
            "FROM game_history WHERE created_at >= NOW() - ($1::interval) "
            "GROUP BY user_id ORDER BY SUM(bet) DESC LIMIT 10", interval
        )
        return rows
    except Exception as exc:
        # Some older installations may have an older game_history schema.
        # Fall back to the persistent aggregate stored on users instead of failing.
        print(f"[LB] Period query failed ({type(exc).__name__}: {exc}); using users.wagered fallback")
        rows = await bot.db.pool.fetch(
            "SELECT user_id, COALESCE(wagered,0) AS wagered FROM users "
            "WHERE COALESCE(wagered,0) > 0 ORDER BY COALESCE(wagered,0) DESC LIMIT 10"
        )
        return rows

@prefix_command(name="lb", aliases=["leaderboard"])
async def leaderboard_command_final(interaction: PrefixInteraction):
    try:
        if bot.db is None or getattr(bot.db, "pool", None) is None:
            await interaction.response.send_message(embed=error_embed("Leaderboard Unavailable", "The database is still starting. Please try again shortly."))
            return
        rows = await fetch_leaderboard_rows("Daily")
        view = LeaderboardView(rows, "Daily", interaction.user.id)
        await interaction.response.send_message(view=view)
    except Exception as exc:
        print(f"[LB] Command error: {type(exc).__name__}: {exc}")
        # Last-resort fallback keeps .lb usable even if the period query fails.
        try:
            rows = await bot.db.pool.fetch(
                "SELECT user_id, COALESCE(wagered,0) AS wagered FROM users "
                "WHERE COALESCE(wagered,0) > 0 ORDER BY COALESCE(wagered,0) DESC LIMIT 10"
            )
            view = LeaderboardView(rows, "Daily", interaction.user.id)
            await interaction.response.send_message(view=view)
        except Exception as fallback_exc:
            print(f"[LB] Fallback error: {type(fallback_exc).__name__}: {fallback_exc}")
            await interaction.response.send_message(embed=error_embed("Leaderboard Unavailable", "Could not load leaderboard data. Check Railway logs for `[LB]` errors."))

