@prefix_command(name="clear")
@bot_owner_only()
async def clear_user_command(interaction: PrefixInteraction, user: str):
    """Reset one user's balance and casino statistics without deleting the account row."""
    if not await require_database(interaction):
        return
    user_id = _target_user_id(user)
    if user_id is None:
        await interaction.response.send_message(embed=error_embed("Invalid Arguments", "Correct usage: `.clear @user`")); return
    try:
        async with bot.db.pool.acquire() as conn:
            await conn.execute("INSERT INTO users(user_id) VALUES($1) ON CONFLICT(user_id) DO NOTHING", user_id)
            await conn.execute("""
                UPDATE users SET
                    balance=0, vault=0, wagered=0, won_games=0, games_played=0, losses=0,
                    rakeback=0, rakeback_total=0, lifetime_deposit=0, lifetime_withdraw=0,
                    affiliate_earnings=0, rank_index=0, rank_reward_claimed=0,
                    daily_wager=0, weekly_wager=0, monthly_wager=0, race_wager=0,
                    total_tips_sent=0, total_tips_received=0, total_rain_received=0,
                    daily_claim_at=NULL, updated_at=NOW()
                WHERE user_id=$1
            """, user_id)
        await interaction.response.send_message(embed=success_embed("User Cleared", f"Reset balance, vault, wagering, game stats, tips, deposits, withdrawals, rank, and daily claim for <@{user_id}>."))
    except Exception as exc:
        print(f"[CLEAR] Failed to reset user {user_id}: {type(exc).__name__}: {exc}")
        await interaction.response.send_message(embed=error_embed("Clear Failed", "Could not reset this user's data. Check Railway logs for `[CLEAR]`."))


@prefix_command(name="createcode")
@bot_owner_only()
async def createcode_command(interaction: PrefixInteraction, code_name: str, amount_per_person: str, total_claim_amount: str):
    """Create an owner-only promo code with a fixed per-user reward and total budget."""
    if bot.db is None or getattr(bot.db, "pool", None) is None:
        await interaction.response.send_message(embed=error_embed("Promo Code", "The database is still starting. Please try again shortly.")); return
    code = re.sub(r"[^A-Za-z0-9_-]", "", str(code_name)).upper()
    if not code or len(code) > 64:
        await interaction.response.send_message(embed=error_embed("Invalid Code", "Use a code name of 1–64 letters, numbers, `_` or `-`. Example: `.createcode WELCOME 1 100`")); return
    reward = normalize_amount(amount_per_person)
    total = normalize_amount(total_claim_amount)
    if reward is None or total is None or reward <= 0 or total <= 0:
        await interaction.response.send_message(embed=error_embed("Invalid Amount", "Both the per-person amount and total claim amount must be greater than zero. Example: `.createcode WELCOME 1 100`")); return
    max_uses = int(total // reward)
    if max_uses < 1:
        await interaction.response.send_message(embed=error_embed("Total Too Small", "The total claim amount must be at least the amount per person.")); return
    try:
        async with bot.db.pool.acquire() as conn:
            # Required by the existing .claim flow; migrations are safe to repeat.
            await conn.execute("ALTER TABLE promo_codes ADD COLUMN IF NOT EXISTS required_deposit NUMERIC(20,8) NOT NULL DEFAULT 0")
            await conn.execute("ALTER TABLE promo_codes ADD COLUMN IF NOT EXISTS required_status TEXT NOT NULL DEFAULT ''")
        await bot.db.create_code(code, reward, max_uses, 0, interaction.user.id)
        await bot.db.pool.execute(
            "UPDATE promo_codes SET required_deposit=0, required_status='', active=TRUE WHERE code=$1",
            code,
        )
    except Exception as exc:
        print(f"[CREATECODE] Failed to create {code}: {type(exc).__name__}: {exc}")
        await interaction.response.send_message(embed=error_embed("Promo Code Error", "Could not create that code. It may already exist; check Railway logs if the problem continues.")); return
    available_total = reward * max_uses
    await interaction.response.send_message(embed=success_embed(
        "Promo Code Created",
        f"**Code:** `{code}`\n**Per person:** {money(reward)}\n**Total claim budget:** {money(total)}\n**Maximum claims:** {max_uses}\n**Actually distributable:** {money(available_total)}\n\nUsers can claim it with `.claim {code}`. Each user can claim this code once."
    ))


