async def _Artic_find_user(user_token):
    uid = _target_user_id(user_token)
    if uid is None:
        return None, None
    member = bot.get_user(uid)
    if member is None:
        try:
            member = await bot.fetch_user(uid)
        except Exception:
            member = None
    return uid, member

async def _Artic_log_channel(setting_key):
    try:
        raw = await bot.db.setting(setting_key, "0")
        channel_id = int(raw or 0)
        return bot.get_channel(channel_id) if channel_id else None
    except Exception:
        return None

@prefix_command(name="admindeposit")
@bot_owner_only()
async def admindeposit_command(interaction: PrefixInteraction, user: str, amount: str):
    """Manually credit a deposit in points and post a deposit alert."""
    if not await require_database(interaction):
        return
    user_id, member = await _Artic_find_user(user)
    value = usd_from_points_admin(amount)
    if user_id is None or value is None:
        await interaction.response.send_message(embed=error_embed("Invalid Arguments", "Correct usage: `.admindeposit @user 100`")); return
    await bot.db.user(user_id)
    ok = await bot.db.change_balance(user_id, value, kind="manual_deposit", note="Manual deposit credited by owner")
    if not ok:
        await interaction.response.send_message(embed=error_embed("Deposit Failed", "Could not credit this user's balance.")); return
    await bot.db.pool.execute("UPDATE users SET lifetime_deposit=COALESCE(lifetime_deposit,0)+$2, updated_at=NOW() WHERE user_id=$1", user_id, value)
    username = member.name if member else str(user_id)
