# Market chart: grey horizontal reference line and a red projected move.
def _market_chart_bytes(direction):
    img=Image.new('RGB',(1000,420),(255,255,255)); draw=ImageDraw.Draw(img)
    for x in range(0,1000,50): draw.line((x,0,x,420),fill=(21,36,57),width=1)
    for y in range(0,420,42): draw.line((0,y,1000,y),fill=(21,36,57),width=1)
    mid=210
    draw.line((35,mid,965,mid),fill=(165,174,188),width=3)
    pts=[(35,mid),(120,mid-5),(200,mid+3),(280,mid-2),(360,mid+1),(445,mid-4),(520,mid+4),(600,mid)]
    if direction=='UP': tail=[(680,mid-22),(750,mid-48),(825,mid-65),(900,mid-105),(965,mid-130)]
    else: tail=[(680,mid+22),(750,mid+48),(825,mid+65),(900,mid+105),(965,mid+130)]
    draw.line(pts+tail,fill=(240,68,76),width=5,joint='curve')
    draw.ellipse((950,tail[-1][1]-8,966,tail[-1][1]+8),fill=(240,68,76))
    buf=io.BytesIO(); img.save(buf,format='PNG'); buf.seek(0); return buf

class MarketPredictionView(discord.ui.View):
    def __init__(self, owner_id, bet):
        super().__init__(timeout=90); self.owner_id=owner_id; self.bet=bet; self.used=False
    async def choose(self, interaction, prediction):
        if interaction.user.id != self.owner_id:
            await interaction.response.send_message("This prediction belongs to another player.", ephemeral=True); return
        if self.used:
            await interaction.response.send_message("This prediction has already been settled.", ephemeral=True); return
        self.used=True
        for child in self.children: child.disabled=True
        await interaction.response.edit_message(view=self)
        await asyncio.sleep(2)
        actual=random.choice(['UP','DOWN'])
        won=prediction==actual
        server_seed=secrets.token_hex(24); client_seed=str(self.owner_id); nonce=secrets.token_hex(8)
        digest=hashlib.sha256(f"{server_seed}:{client_seed}:{nonce}".encode()).hexdigest()
        if won:
            payout=(self.bet*Decimal('1.90')).quantize(Decimal('0.01'),rounding=ROUND_DOWN)
            await bot.db.change_balance(self.owner_id,payout,kind='game_payout',note='Market prediction win')
            title='<:Trading:1558000990236577872> Market Prediction - Won'; desc=f"The market moved **{actual.lower()}** as predicted. You won **{points_text(payout)}**."
            color=0x57F287
        else:
            title='<:Trading:1558000990236577872> Market Prediction - Liquidated'; desc=f"The market moved against you. You lost **{points_text(self.bet)}**."
            color=0xED4245
        desc += f"\n\n🔒 **Provably Fair**\n**Server Seed:** `{server_seed}`\n**Client Seed:** `{client_seed}`\n**Nonce:** `{nonce}`\n**SHA-256:** `{digest}`"
        embed=base_embed(title,desc,color)
        chart=discord.File(_market_chart_bytes(actual),filename='market.png')
        embed.set_image(url='attachment://market.png')
        await interaction.edit_original_response(embed=embed, view=self, attachments=[chart])
    @discord.ui.button(label='Up',style=discord.ButtonStyle.success)
    async def up(self, interaction, button): await self.choose(interaction,'UP')
    @discord.ui.button(label='Down',style=discord.ButtonStyle.danger)
    async def down(self, interaction, button): await self.choose(interaction,'DOWN')

@prefix_command(name="market")
async def market_command(interaction: PrefixInteraction, amount: str):
    if not await require_database(interaction): return
    bet=usd_from_points_input(amount,await bot.get_balance(interaction.user.id))
    if bet is None or bet < MIN_BET:
        await interaction.response.send_message(embed=error_embed("Invalid Arguments", "Correct usage: `.market 100`")); return
    if not await bot.deduct_bet(interaction.user.id,bet,'market_prediction'):
        await interaction.response.send_message(embed=error_embed("Insufficient Balance", "You don't have enough points for this bet.")); return
    # Grey baseline and a neutral, not-yet-revealed chart until the user chooses.
    buf=Image.new('RGB',(1000,420),(255,255,255)); d=ImageDraw.Draw(buf)
    for x in range(0,1000,50): d.line((x,0,x,420),fill=(21,36,57),width=1)
    for y in range(0,420,42): d.line((0,y,1000,y),fill=(21,36,57),width=1)
    d.line((35,210,965,210),fill=(165,174,188),width=3)
    d.line([(35,210),(150,203),(240,215),(340,207),(430,213),(520,206),(610,210)],fill=(240,68,76),width=4)
    bufio=io.BytesIO(); buf.save(bufio,format='PNG'); bufio.seek(0)
    embed=base_embed('<:Trading:1558000990236577872> Market Prediction', f"**Bet:** {points_text(bet)} · `{money(bet)}`\n\nChoose Prediction", GAME_COLOR)
    embed.set_image(url='attachment://market.png')
    await interaction.response.send_message(embed=embed,file=discord.File(bufio,filename='market.png'),view=MarketPredictionView(interaction.user.id,bet))

class StakeView(discord.ui.View):
    def __init__(self, owner_id, bet, difficulty=None):
        super().__init__(timeout=120); self.owner_id=owner_id; self.bet=bet; self.difficulty=difficulty; self.picked=set(); self.over=False; self.safe=[]; self.multiplier=Decimal('1.0')
        if difficulty: self._build_game()
        else: self._build_choice()
    async def interaction_check(self, interaction):
        if interaction.user.id != self.owner_id:
            await interaction.response.send_message("This game belongs to another player.",ephemeral=True); return False
        return True
    def _build_choice(self):
        self.clear_items()
        for diff in ('easy','hard'):
            b=discord.ui.Button(label=diff.title(),style=discord.ButtonStyle.primary)
            async def cb(interaction, difficulty=diff):
                self.difficulty=difficulty; self.safe=random.sample(range(1,5), 3 if difficulty=='easy' else 2); self._build_game(); await interaction.response.edit_message(embed=self._embed(),view=self)
            b.callback=cb; self.add_item(b)
    def _build_game(self):
        self.clear_items()
        for i in range(1,5):
            b=discord.ui.Button(label=str(i),style=discord.ButtonStyle.secondary,disabled=self.over or i in self.picked)
            async def cb(interaction, number=i): await self.pick(interaction,number)
            b.callback=cb; self.add_item(b)
        cash=discord.ui.Button(label='Cash Out',emoji='💰',style=discord.ButtonStyle.success,disabled=self.over or not self.picked)
        async def cash_cb(interaction): await self.cashout(interaction)
        cash.callback=cash_cb; self.add_item(cash)
    def _embed(self, result=None, color=None):
        difficulty=(self.difficulty or 'choose').title()
        icons='  '.join('☠️' if (self.over and i not in self.safe) else ('🍖' if i in self.picked else '🍖') for i in range(1,5))
        nums='  '.join(f"`{i}`" if i not in self.picked else f"**{i}**" for i in range(1,5))
        desc=f"**Bet:** {points_text(self.bet)} · `{money(self.bet)}`\n**Difficulty:** {difficulty}\n\n{icons}\n\n{nums}"
        if self.picked: desc+=f"\n\n**Multiplier:** {self.multiplier}x"
        if result: desc+='\n\n'+result
        return base_embed('Stake',desc,color if color is not None else GAME_COLOR)
    async def pick(self, interaction, number):
        if self.over: await interaction.response.send_message('This game has ended.',ephemeral=True); return
        self.picked.add(number)
        if number not in self.safe:
            self.over=True
            self.safe=set(self.safe)
            for child in self.children: child.disabled=True
            await interaction.response.edit_message(embed=self._embed(f"☠️ Poisonous meat! You lost **{points_text(self.bet)}**.",0xED4245),view=self); return
        count=len(self.picked)
        if self.difficulty=='easy': self.multiplier=[Decimal('1.20'),Decimal('2.00'),Decimal('5.00')][min(count-1,2)]
        else: self.multiplier=Decimal('2.00') if count==1 else Decimal('10.00')
        self._build_game(); await interaction.response.edit_message(embed=self._embed('Safe pick! Continue or cash out.'),view=self)
    async def cashout(self, interaction):
        if self.over or not self.picked: await interaction.response.send_message('Make a safe pick first.',ephemeral=True); return
        self.over=True; payout=(self.bet*self.multiplier).quantize(Decimal('0.01'),rounding=ROUND_DOWN)
        await bot.db.change_balance(self.owner_id,payout,kind='game_payout',note='Stake cashout')
        for child in self.children: child.disabled=True
        await interaction.response.edit_message(embed=self._embed(f"<:Party:1557392288131584001> Cashed out **{points_text(payout)}** at **{self.multiplier}x**.",0x57F287),view=self)

@prefix_command(name="stake")
async def stake_command(interaction: PrefixInteraction, amount: str, difficulty: str = ""):
    if not await require_database(interaction): return
    bet=usd_from_points_input(amount,await bot.get_balance(interaction.user.id))
    if bet is None or bet < MIN_BET:
        await interaction.response.send_message(embed=error_embed("Invalid Arguments", "Correct usage: `.stake 100 [easy/hard]`")); return
    if difficulty and difficulty.lower() not in {'easy','hard'}:
        await interaction.response.send_message(embed=error_embed("Invalid Arguments", "Difficulty must be `easy` or `hard`.")); return
    if not await bot.deduct_bet(interaction.user.id,bet,'stake'):
        await interaction.response.send_message(embed=error_embed("Insufficient Balance", "You don't have enough points for this bet.")); return
    view=StakeView(interaction.user.id,bet,difficulty.lower() if difficulty else None)
    await interaction.response.send_message(embed=view._embed(),view=view)


# ============================================================
# ARTIC REWARD DASHBOARD + DEPOSIT BONUS ADMIN
# ============================================================

async def _artic_reward_tables():
    if not getattr(bot, 'db', None) or not getattr(bot.db, 'pool', None):
        return
    async with bot.db.pool.acquire() as conn:
        await conn.execute("""
            CREATE TABLE IF NOT EXISTS artic_reward_settings (
                setting_key TEXT PRIMARY KEY, setting_value TEXT NOT NULL DEFAULT ''
            )
        """)
        await conn.execute("""
            CREATE TABLE IF NOT EXISTS artic_invites (
                user_id BIGINT PRIMARY KEY, invite_count INTEGER NOT NULL DEFAULT 0,
                claimed_count INTEGER NOT NULL DEFAULT 0
            )
        """)
        await conn.execute("""
            CREATE TABLE IF NOT EXISTS artic_invite_codes (
                invite_code TEXT PRIMARY KEY, inviter_id BIGINT NOT NULL,
                uses INTEGER NOT NULL DEFAULT 0
            )
        """)

async def _artic_setting(key, default=''):
    await _artic_reward_tables()
    async with bot.db.pool.acquire() as conn:
        row = await conn.fetchrow('SELECT setting_value FROM artic_reward_settings WHERE setting_key=$1', key)
    return str(row['setting_value']) if row else default

async def _artic_set_setting(key, value):
    await _artic_reward_tables()
    async with bot.db.pool.acquire() as conn:
        await conn.execute('INSERT INTO artic_reward_settings(setting_key,setting_value) VALUES($1,$2) ON CONFLICT(setting_key) DO UPDATE SET setting_value=EXCLUDED.setting_value', key, str(value))

async def _artic_invite_listener(member):
    """Track newly joined members by comparing the guild's invite usage."""
    try:
        await _artic_reward_tables()
        current = await member.guild.invites()
        # On first observation, seed counts without awarding historical joins.
        cache = getattr(bot, '_artic_invite_cache', {})
        old = cache.get(member.guild.id)
        now = {i.code: (i.uses or 0, i.inviter.id if i.inviter else 0) for i in current}
        cache[member.guild.id] = now
        bot._artic_invite_cache = cache
        if old is None:
            return
        used = next((code for code, (uses, inviter) in now.items() if uses > old.get(code, (uses, inviter))[0] and inviter), None)
        if not used:
            return
        inviter_id = now[used][1]
        if inviter_id == member.id:
            return
        async with bot.db.pool.acquire() as conn:
            await conn.execute('INSERT INTO artic_invites(user_id,invite_count,claimed_count) VALUES($1,1,0) ON CONFLICT(user_id) DO UPDATE SET invite_count=artic_invites.invite_count+1', inviter_id)
    except Exception as exc:
        print(f'[ARTIC INVITE TRACKER] {type(exc).__name__}: {exc}')

bot.add_listener(_artic_invite_listener, 'on_member_join')

async def _artic_reward_values(user_id):
    await _artic_reward_tables()
    async with bot.db.pool.acquire() as conn:
        row = await conn.fetchrow('SELECT COALESCE(rakeback,0) AS rakeback, COALESCE(daily_claim_at, NULL) AS daily_claim_at FROM users WHERE user_id=$1', user_id)
        inv = await conn.fetchrow('SELECT invite_count, claimed_count FROM artic_invites WHERE user_id=$1', user_id)
    rake = D(row['rakeback'] if row else 0)
    daily_available = not row or not row['daily_claim_at'] or row['daily_claim_at'] <= datetime.now(timezone.utc)-timedelta(hours=24)
    invite_count = int(inv['invite_count'] if inv else 0)
    claimed_count = int(inv['claimed_count'] if inv else 0)
    invite_claimable = Decimal(max(0, invite_count-claimed_count)) * Decimal('0.20')
    bonus_active = (await _artic_setting('deposit_bonus', '0')).lower() not in ('0','off','stop','')
    bonus_pct = D(await _artic_setting('deposit_bonus', '0')) if bonus_active else Decimal('0')
    async with bot.db.pool.acquire() as conn:
        dep = await conn.fetchrow('SELECT COALESCE(lifetime_deposit,0) AS lifetime_deposit FROM users WHERE user_id=$1', user_id)
    # Deposit bonus accrual is credited from the deposit watcher when a deposit is confirmed;
    # dashboard value is stored separately so claims cannot duplicate a deposit credit.
    async with bot.db.pool.acquire() as conn:
        await conn.execute('ALTER TABLE users ADD COLUMN IF NOT EXISTS deposit_bonus_claimable NUMERIC(20,4) NOT NULL DEFAULT 0')
        b = await conn.fetchval('SELECT deposit_bonus_claimable FROM users WHERE user_id=$1', user_id)
    deposit_bonus = D(b or 0)
    daily = Decimal('0.02') if daily_available else Decimal('0')
    return {'rakeback':rake, 'daily':daily, 'invite':invite_claimable, 'deposit':deposit_bonus, 'bonus_pct':bonus_pct, 'invite_count':invite_count, 'claimed_invites':claimed_count}

def _artic_reward_image(username, earned, claimable, claimed, rows):
    """Render the clean white rewards dashboard shown in the reference image."""
    W, H = 1536, 790
    im = Image.new("RGB", (W, H), (255, 255, 255))
    d = ImageDraw.Draw(im)

    def f(sz, bold=False):
        paths = (
            ["/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf",
             "/usr/share/fonts/truetype/liberation2/LiberationSans-Bold.ttf"]
            if bold else
            ["/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf",
             "/usr/share/fonts/truetype/liberation2/LiberationSans-Regular.ttf"]
        )
        for path in paths:
            try:
                return ImageFont.truetype(path, sz)
            except Exception:
                pass
        return ImageFont.load_default()

    ink = (18, 25, 23)          # dark obsidian text
    muted = (48, 55, 52)
    border = (225, 227, 226)
    panel = (255, 255, 255)
    green = (36, 145, 89)

    d.text((70, 48), "✿ CryptoBet", font=f(38, True), fill=ink)
    d.text((1280, 60), "All rewards", font=f(24), fill=ink)
    d.line((68, 122, 1468, 122), fill=border, width=2)

    cards = [
        ("TOTAL EARNED", earned),
        ("TOTAL CLAIMABLE", claimable),
        ("TOTAL CLAIMED", claimed),
    ]
    for i, (label, val) in enumerate(cards):
        x = 68 + i * 475
        d.rounded_rectangle((x, 158, x + 453, 298), radius=28,
                            fill=panel, outline=border, width=2)
        d.text((x + 34, 190), label, font=f(16, True), fill=muted)
        d.text((x + 34, 225), f"${D(val):.2f}", font=f(42, True), fill=ink)

    d.text((102, 340), "CATEGORY", font=f(16, True), fill=muted)
    d.text((920, 340), "EARNED", font=f(16, True), fill=muted)
    d.text((1320, 340), "CLAIMABLE", font=f(16, True), fill=muted)

    names = ["Rakeback", "Daily rewards", "Invite rewards", "Deposit Bonus"]
    safe_rows = list(rows[:4])
    while len(safe_rows) < 4:
        safe_rows.append((Decimal("0"), Decimal("0")))
    for i, name in enumerate(names):
        y = 385 + i * 94
        d.rounded_rectangle((68, y, 1468, y + 78), radius=26,
                            fill=panel, outline=border, width=2)
        d.text((102, y + 18), name, font=f(28, True), fill=ink)
        d.text((900, y + 18), f"${D(safe_rows[i][0]):.2f}",
               font=f(28, True), fill=ink)
        d.text((1320, y + 18), f"${D(safe_rows[i][1]):.2f}",
               font=f(28, True), fill=ink)

    out = io.BytesIO()
    im.save(out, "PNG", optimize=True)
    out.seek(0)
    return discord.File(out, filename="cryptobet_rewards.png")

class ArticRewardsView(discord.ui.View):
    def __init__(self, owner_id, values):
        super().__init__(timeout=180)
        self.owner_id=owner_id
        self.values=values
        for label,key in [('Rakeback','rakeback'),('Daily','daily'),('Invite Reward','invite'),('Deposit Bonus','deposit')]:
            b=discord.ui.Button(label=label,style=discord.ButtonStyle.secondary,row=0)
            async def cb(interaction, reward_key=key):
                if interaction.user.id != self.owner_id:
                    await interaction.response.send_message('These rewards belong to another user.',ephemeral=True); return
                await self.claim(interaction,reward_key)
            b.callback=cb; self.add_item(b)
        allb=discord.ui.Button(label='Claim All',style=discord.ButtonStyle.primary,row=1)
        async def all_cb(interaction):
            if interaction.user.id != self.owner_id:
                await interaction.response.send_message('These rewards belong to another user.',ephemeral=True); return
            await self.claim(interaction,'all')
        allb.callback=all_cb; self.add_item(allb)
    async def claim(self, interaction, key):
        if not await require_database(interaction): return
        uid=self.owner_id
        vals=await _artic_reward_values(uid)
        keys=['rakeback','daily','invite','deposit'] if key=='all' else [key]
        total=Decimal('0'); messages=[]
        for k in keys:
            amount=vals[k]
            if amount<=0: continue
            try:
                if k=='rakeback':
                    got=await bot.db.claim_rakeback(uid)
                    amount=D(got)
                elif k=='daily':
                    async with bot.db.pool.acquire() as conn:
                        claimed=await conn.fetchrow("UPDATE users SET daily_claim_at=NOW(), updated_at=NOW() WHERE user_id=$1 AND (daily_claim_at IS NULL OR daily_claim_at <= NOW()-INTERVAL '24 hours') RETURNING user_id",uid)
                    if not claimed: amount=Decimal('0')
                elif k=='invite':
                    async with bot.db.pool.acquire() as conn:
                        row=await conn.fetchrow('SELECT invite_count,claimed_count FROM artic_invites WHERE user_id=$1 FOR UPDATE',uid)
                        count=max(0,int(row['invite_count'] if row else 0)-int(row['claimed_count'] if row else 0))
                        amount=Decimal(count)*Decimal('0.20')
                        if count: await conn.execute('UPDATE artic_invites SET claimed_count=invite_count WHERE user_id=$1',uid)
                elif k=='deposit':
                    async with bot.db.pool.acquire() as conn:
                        amount=D(await conn.fetchval('WITH old AS (SELECT deposit_bonus_claimable AS amount FROM users WHERE user_id=$1 FOR UPDATE) UPDATE users SET deposit_bonus_claimable=0 WHERE user_id=$1 RETURNING (SELECT amount FROM old)',uid) or 0)
                if amount>0:
                    await bot.db.change_balance(uid,amount,kind='reward_claim',note=f'Artic {k} reward claim')
                    total+=amount; messages.append(f'{k}: ${amount:.2f}')
            except Exception as exc:
                print(f'[ARTIC REWARD CLAIM] {k}: {type(exc).__name__}: {exc}')
        if total<=0:
            await interaction.response.send_message('No rewards are currently claimable.',ephemeral=True); return
        balance=await bot.get_balance(uid)
        vals=await _artic_reward_values(uid)
        earned=vals['rakeback']+vals['invite']+vals['deposit']
        rows=[(vals['rakeback'],vals['rakeback']),(Decimal('0.02'),vals['daily']),(Decimal(vals['invite_count'])*Decimal('0.20'),vals['invite']),(vals['deposit'],vals['deposit'])]
        file=_artic_reward_image(interaction.user.display_name,earned,total,total,rows)
        await interaction.response.send_message(content=f'Claimed **${total:.2f}**. New balance: **{money(balance)}**.',file=file,ephemeral=True)

@prefix_command(name='reward', aliases=['rw','rewards'])
async def artic_reward_command(interaction: PrefixInteraction):
    if not await require_database(interaction): return
    vals=await _artic_reward_values(interaction.user.id)
    claimed_total=D(await bot.db.pool.fetchval("SELECT COALESCE(SUM(amount),0) FROM transactions WHERE user_id=$1 AND kind='reward_claim'",interaction.user.id) or 0) if False else Decimal('0')
    earned=vals['rakeback']+vals['invite']+vals['deposit']
    rows=[(vals['rakeback'],vals['rakeback']),(Decimal('0.02'),vals['daily']),(Decimal(vals['invite_count'])*Decimal('0.20'),vals['invite']),(vals['deposit'],vals['deposit'])]
    file=_artic_reward_image(interaction.user.display_name,earned,sum(v for v in [vals['rakeback'],vals['daily'],vals['invite'],vals['deposit']]),claimed_total,rows)
    view=ArticRewardsView(interaction.user.id,vals)
    await interaction.response.send_message(file=file,view=view)

@prefix_command(name='depobonus')
@prefix_owner_only()
async def artic_depobonus_command(interaction: PrefixInteraction, value: str):
    if not await require_database(interaction): return
    if value.lower() in {'stop','off','disable'}:
        await _artic_set_setting('deposit_bonus','0')
        await interaction.response.send_message(embed=success_embed('Deposit Bonus','Deposit bonus has been stopped.'))
        return
    try: pct=Decimal(value.replace('%',''))
    except Exception:
        await interaction.response.send_message(embed=error_embed('Deposit Bonus','Usage: `.depobonus 50` or `.depobonus stop`')); return
    if pct<0 or pct>1000:
        await interaction.response.send_message(embed=error_embed('Deposit Bonus','Enter a percentage from 0 to 1000.')); return
    await _artic_set_setting('deposit_bonus',str(pct))
    await interaction.response.send_message(embed=success_embed('Deposit Bonus',f'Deposit bonus set to **{pct}%**.'))

